    min: +(sorted[0] ?? 0).toFixed(SCORE_DISPLAY_PRECISION),
    max: +(sorted[sorted.length - 1] ?? 0).toFixed(SCORE_DISPLAY_PRECISION),
    count: sorted.length,
  };
