}import { Fragment, useCallback, useMemo, useState } from 'react';
import type { CSSProperties } from 'react';
import type { AgentStat, EvalMetricSummary } from '../hooks/useAgentStats.js';
import { scoreColor, scoreColorBand, fmtBytes, formatPercent, byValueDesc } from '../lib/quality-utils.js';
import { TruncatedIdLink } from './TruncatedIdLink.js';
import {
  AGENT_PALETTE, ERROR_RATE_WARNING_THRESHOLD,
  SPARKLINE_WIDTH, SPARKLINE_HEIGHT, SCORE_CHIP_PRECISION,
} from '../lib/constants.js';
import { routes } from '../lib/routes.js';
import { BarIndicator } from './BarIndicator.js';
import { EmptyState } from './EmptyState.js';
import { ExpandChevron } from './ExpandChevron.js';
import { Sparkline } from './Sparkline.js';
import { StatDisplay } from './StatDisplay.js';
const COLUMN_COUNT = 7;
type SortKey = 'invocations' | 'errorRate' | 'sessionCount' | 'avgOutputSize';
interface IdListColumnProps {
  label: string;
  ids: string[];
  totalCount: number;
  isTruncated: boolean;
  routeFn: (id: string) => string;
}
function IdListColumn({ label, ids, totalCount, isTruncated, routeFn }: IdListColumnProps) {
  return (
    <div>
      <div className="text-muted mb-1-5 text-xs uppercase">{label} ({totalCount})</div>
      <div className="flex-col gap-1">
        {ids.map(id => (
          <TruncatedIdLink
            key={id}
            id={id}
            href={routeFn(id)}
            maxLen={12}
            onClick={(e) => e.stopPropagation()}
          />
        ))}
        {ids.length === 0 && <span className="text-muted text-xs">none</span>}
        {isTruncated && (
          <span className="text-muted text-2xs italic">+{totalCount - ids.length} more</span>
        )}
      </div>
    </div>
  );
}
function errorRateColor(rate: number): string {
  if (rate === 0) return 'var(--status-healthy)';
  if (rate < ERROR_RATE_WARNING_THRESHOLD) return 'var(--status-warning)';
  return 'var(--status-critical)';
}
interface AgentActivityPanelProps {
  agents: AgentStat[];
}
export function AgentActivityPanel({ agents }: AgentActivityPanelProps) {
  const [sort, setSort] = useState<SortKey>('invocations');
  const [asc, setAsc] = useState(false);
  const [expanded, setExpanded] = useState<string | null>(null);
  const colorIndex = useMemo(
    () => {
      const m = new Map<string, string>();
      for (let i = 0; i < agents.length; i++) {
        const a = agents[i];
        if (!a) continue;
        m.set(a.agentName, AGENT_PALETTE[i % AGENT_PALETTE.length] ?? AGENT_PALETTE[0]);
      }
      return m;
    },
    [agents],
  );
  const toggleSort = useCallback((key: SortKey) => {
    if (key === sort) {
      setAsc(v => !v);
    } else {
      setSort(key);
      setAsc(false);
    }
  }, [sort]);
  if (agents.length === 0) {
    return <EmptyState message="No agent activity recorded for this period." />;
  }
  const maxInvocations = Math.max(...agents.map(a => a.invocations), 1);
  const sorted = [...agents].sort((a, b) => {
    const diff = a[sort] < b[sort] ? -1 : a[sort] > b[sort] ? 1 : 0;
    return asc ? diff : -diff;
  });
  const sortIndicator = (key: SortKey) =>
    sort === key ? (asc ? ' \u2191' : ' \u2193') : '';
  return (
    <div className="overflow-x-auto">
      <table className="data-table sla-table agent-activity-table">
        <thead>
          <tr>
            <th className="col-agent">Agent</th>
            <th className="cursor-pointer select-none" onClick={() => toggleSort('invocations')}>
              Invocations{sortIndicator('invocations')}
            </th>
            <th className="cursor-pointer select-none" onClick={() => toggleSort('errorRate')}>
              Error Rate{sortIndicator('errorRate')}
            </th>
            <th className="cursor-pointer select-none" onClick={() => toggleSort('sessionCount')}>
              Sessions{sortIndicator('sessionCount')}
            </th>
            <th className="cursor-pointer select-none" onClick={() => toggleSort('avgOutputSize')}>
              Avg Output{sortIndicator('avgOutputSize')}
            </th>
            <th>Rate Limits</th>
            <th>Source</th>
          </tr>
        </thead>
        <tbody>
          {sorted.map((agent) => {
            const color = colorIndex.get(agent.agentName) ?? AGENT_PALETTE[0];
            const errStatus = agent.errorRate === 0 ? 'ok' : agent.errorRate < ERROR_RATE_WARNING_THRESHOLD ? 'warn' : 'critical';
            const invPct = (agent.invocations / maxInvocations) * 100;
            const topSource = Object.entries(agent.sourceTypes).sort(byValueDesc)[0]?.[0];
            const isExpanded = expanded === agent.agentName;
            const hasLinks = agent.sessionIds.length > 0 || agent.traceIds.length > 0;
            return (
              <Fragment key={agent.agentName}>
                <tr
                  className={`valign-middle${isExpanded ? ' eval-row-expanded' : ''}${hasLinks ? ' cursor-pointer' : ''}`}
                  style={{ '--agent-color': color } as CSSProperties}
                  onClick={() => hasLinks && setExpanded(isExpanded ? null : agent.agentName)}
                >
                  <td>
                    <div className="flex-center gap-2">
                      {hasLinks && (
                        <ExpandChevron expanded={isExpanded} className="text-2xs text-muted shrink-0" />
                      )}
                      <span className="dot-sm agent-dot" />
                      <span className="mono-xs text-primary break-all">
                        {agent.agentName}
                      </span>
                    </div>
                  </td>
                  <td>
                    <div className="flex-center gap-2">
                      <span className="mono-xs agent-inv-count">
                        {agent.invocations}
                      </span>
                      <BarIndicator value={invPct} color={color} opacity={0.7} className="flex-1 agent-inv-bar" />
                    </div>
                  </td>
                  <td>
                    <div className="flex-center gap-1-5">
                      <span className="mono-xs agent-err-rate" data-err-status={errStatus}>
                        {agent.errors > 0 ? formatPercent(agent.errorRate * 100) : '\u2014'}
                      </span>
                      {agent.errors > 0 && (
                        <span className="text-muted text-xs">
                          ({agent.errors})
                        </span>
                      )}
                    </div>
                  </td>
                  <td>
                    <span className="mono-xs">
                      {agent.sessionCount}
                    </span>
                  </td>
                  <td>
                    <span className="mono-xs text-secondary">
                      {fmtBytes(agent.avgOutputSize)}
                    </span>
                  </td>
                  <td>
                    {agent.rateLimitCount > 0 ? (
                      <span className="mono-xs badge-warning">
                        {agent.rateLimitCount}x
                      </span>
                    ) : (
                      <span className="text-muted text-xs">{'\u2014'}</span>
                    )}
                  </td>
                  <td>
                    {topSource ? (
                      <span className="mono text-muted text-2xs uppercase">
                        {topSource}
                      </span>
                    ) : <span className="text-muted">{'\u2014'}</span>}
                  </td>
                </tr>
                {isExpanded && (
                  <tr className="eval-expanded-panel">
                    <td colSpan={COLUMN_COUNT} className="border-b">
                      <EvalSummaryRow evalSummary={agent.evalSummary} />
                      {agent.dailyCounts.length > 1 && agent.dailyCounts.some(v => v > 0) && (
                        <div className="border-b-subtle mb-1 pad-panel-section">
                          <div className="flex-center gap-3">
                            <div className="text-xs text-muted uppercase shrink-0">
                              Daily Activity
                            </div>
                            <Sparkline
                              data={agent.dailyCounts}
                              width={SPARKLINE_WIDTH}
                              height={SPARKLINE_HEIGHT}
                              color={colorIndex.get(agent.agentName) ?? AGENT_PALETTE[0]}
                              label={`Daily invocations for ${agent.agentName}`}
                            />
                            <span className="mono text-muted text-2xs shrink-0">
                              peak {Math.max(...agent.dailyCounts)}/day
                            </span>
                          </div>
                        </div>
                      )}
                      <div className="agent-expanded-grid">
                        <IdListColumn
                          label="Sessions"
                          ids={agent.sessionIds}
                          totalCount={agent.sessionCount}
                          isTruncated={agent.sessionIdsTruncated}
                          routeFn={routes.session}
                        />
                        <IdListColumn
                          label="Traces"
                          ids={agent.traceIds}
                          totalCount={agent.traceIdsTotal ?? agent.traceIds.length}
                          isTruncated={agent.traceIdsTruncated}
                          routeFn={routes.trace}
                        />
                      </div>
                    </td>
                  </tr>
                )}
              </Fragment>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}
function EvalSummaryRow({ evalSummary }: { evalSummary: Record<string, EvalMetricSummary> }) {
  const metrics = Object.entries(evalSummary);
  if (metrics.length === 0) {
    return (
      <div className="text-xs text-muted border-b-subtle mb-1 pad-panel-sparse">
        No evaluations linked to this agent.
      </div>
    );
  }
  return (
    <div className="border-b-subtle mb-1 pad-panel-section">
      <div className="text-muted mb-1-5 text-xs uppercase">
        Evaluation Metrics
      </div>
      <div className="flex-wrap gap-3">
        {metrics.map(([name, m]) => {
          const barColor = scoreColor(m.avg);
          const band = scoreColorBand(m.avg);
          return (
            <div key={name} className="metric-card-compact">
              <div className="text-secondary mb-1 text-xs truncate">
                {name}
              </div>
              <div className="flex-center mb-1 gap-2">
                <BarIndicator value={Math.min(m.avg * 100, 100)} color={barColor} className="flex-1" />
                <span className="mono-xs font-semibold text-right score-label-width score-band" data-band={band}>
                  {m.avg.toFixed(SCORE_CHIP_PRECISION)}
                </span>
              </div>
              <div className="mono text-muted flex-wrap justify-between text-2xs">
                <span>{m.min.toFixed(SCORE_CHIP_PRECISION)}\u2013{m.max.toFixed(SCORE_CHIP_PRECISION)}</span>
                <span>n={m.count}</span>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}
export function AgentActivitySummary({ agents }: AgentActivityPanelProps) {
  const totalInvocations = agents.reduce((s, a) => s + a.invocations, 0);
  const totalErrors = agents.reduce((s, a) => s + a.errors, 0);
  const totalRateLimits = agents.reduce((s, a) => s + a.rateLimitCount, 0);
  const rawErrorRate = totalInvocations > 0 ? totalErrors / totalInvocations : 0;
  const overallErrorRate = rawErrorRate * 100;
  return (
    <div className="d-flex flex-wrap gap-8 surface-elevated mb-5 p-4-5">
      {[
        { label: 'Agents', value: agents.length },
        { label: 'Invocations', value: totalInvocations.toLocaleString() },
        {
          label: 'Error Rate',
          value: totalInvocations > 0 ? formatPercent(overallErrorRate) : '\u2014',
          color: errorRateColor(rawErrorRate),
        },
        {
          label: 'Rate Limits',
          value: totalRateLimits > 0 ? totalRateLimits : '\u2014',
          color: totalRateLimits > 0 ? 'var(--status-warning)' : undefined,
        },
      ].map(({ label, value, color }) => (
        <StatDisplay key={label} value={value} label={label} valueColor={color} />
      ))}
    </div>
  );
}import { ScoreBadge } from './ScoreBadge.js';
interface AgentScoreSummaryProps {
  handoffScore: number;
  avgRelevance: number;
  completeness: number;
}
const SCORES = [
  { label: 'Handoff Score', metricName: 'handoff' },
  { label: 'Avg Relevance', metricName: 'relevance' },
  { label: 'Completeness', metricName: 'completeness' },
] as const;
export function AgentScoreSummary({ handoffScore, avgRelevance, completeness }: AgentScoreSummaryProps) {
  const values = { handoff: handoffScore, relevance: avgRelevance, completeness };
  return (
    <div className="flex-wrap gap-6">
      {SCORES.map(({ label, metricName }) => (
        <div key={label} className="text-center">
          <div className="field-label text-secondary text-xs mb-1">{label}</div>
          <ScoreBadge score={values[metricName]} metricName={metricName} />
        </div>
      ))}
    </div>
  );
}import React, { useState, useCallback, useMemo, useRef } from 'react';
import { WorkflowGraphView } from './WorkflowGraph.js';
import { WorkflowTimeline } from './WorkflowTimeline.js';
import type { WorkflowGraph } from '../types/workflow-graph.js';
import type { MultiAgentEvaluation } from '../types.js';
import { agentColor, fmtDuration } from '../lib/quality-utils.js';
import { WORKFLOW_FILTER_MIN_AGENTS } from '../lib/constants.js';
type WorkflowTab = 'dag' | 'timeline';
interface AgentWorkflowViewProps {
  graph: WorkflowGraph;
  evaluation?: MultiAgentEvaluation;
  onNodeClick?: (nodeId: string) => void;
  height?: number;
}
const TAB_LABELS: Record<WorkflowTab, string> = {
  dag: 'DAG',
  timeline: 'Timeline',
};
const TABS: WorkflowTab[] = ['dag', 'timeline'];
export function AgentWorkflowView({
  graph,
  evaluation,
  onNodeClick,
  height = 600,
}: AgentWorkflowViewProps) {
  const [activeTab, setActiveTab] = useState<WorkflowTab>('dag');
  const agentNames = useMemo(
    () => [...new Set((evaluation?.turns ?? []).map(t => t.agentName ?? 'unknown'))],
    [evaluation?.turns],
  );
  const [selectedAgents, setSelectedAgents] = useState<ReadonlySet<string> | null>(null);
  const [minDurationMs, setMinDurationMs] = useState(0);
  const [errorsOnly, setErrorsOnly] = useState(false);
  const [showCriticalPath, setShowCriticalPath] = useState(false);
  const graphContainerRef = useRef<HTMLDivElement>(null);
  const effectiveSelected: ReadonlySet<string> = useMemo(
    () => selectedAgents ?? new Set(agentNames),
    [selectedAgents, agentNames],
  );
  const maxDurationMs = useMemo(
    () => Math.max(0, ...graph.nodes.map(n => n.durationMs)),
    [graph.nodes],
  );
  const criticalPathSet = useMemo((): ReadonlySet<string> | undefined => {
    if (!showCriticalPath || graph.nodes.length === 0 || graph.rootNodeId === null) return undefined;
    const adj = new Map<string, string[]>();
    for (const n of graph.nodes) adj.set(n.id, []);
    for (const edge of graph.edges) {
      adj.get(edge.source)?.push(edge.target);
    }
    const dur = new Map<string, number>();
    for (const n of graph.nodes) dur.set(n.id, n.durationMs);
    function dfs(nodeId: string, visiting: Set<string>): [string[], number] {
      if (visiting.has(nodeId)) return [[], 0];
      visiting.add(nodeId);
      let bestPath: string[] = [];
      let bestCost = 0;
      for (const child of adj.get(nodeId) ?? []) {
        const [childPath, childCost] = dfs(child, visiting);
        if (childCost > bestCost) {
          bestCost = childCost;
          bestPath = childPath;
        }
      }
      visiting.delete(nodeId);
      return [[nodeId, ...bestPath], (dur.get(nodeId) ?? 0) + bestCost];
    }
    const [path] = dfs(graph.rootNodeId, new Set());
    return new Set(path);
  }, [showCriticalPath, graph.nodes, graph.edges, graph.rootNodeId]);
  const filteredNodeIds = useMemo((): ReadonlySet<string> | undefined => {
    const hasAgentFilter = selectedAgents !== null;
    const hasDurFilter = minDurationMs > 0;
    const hasErrFilter = errorsOnly;
    if (!hasAgentFilter && !hasDurFilter && !hasErrFilter) return undefined;
    let result = new Set(graph.nodes.map(n => n.id));
    if (hasAgentFilter) {
      result = new Set([...result].filter(id => selectedAgents.has(id)));
    }
    if (hasDurFilter) {
      const durPass = new Set(graph.nodes.filter(n => n.durationMs >= minDurationMs).map(n => n.id));
      result = new Set([...result].filter(id => durPass.has(id)));
    }
    if (hasErrFilter) {
      const errPass = new Set(graph.nodes.filter(n => n.hasError).map(n => n.id));
      result = new Set([...result].filter(id => errPass.has(id)));
    }
    return result;
  }, [selectedAgents, minDurationMs, errorsOnly, graph.nodes]);
  const toggleAgent = useCallback((name: string) => {
    setSelectedAgents(prev => {
      const base = prev ?? new Set(agentNames);
      const next = new Set(base);
      if (next.has(name)) {
        next.delete(name);
      } else {
        next.add(name);
      }
      if (next.size === agentNames.length) return null;
      return next;
    });
  }, [agentNames]);
  const selectAll = useCallback(() => setSelectedAgents(null), []);
  const handleExport = useCallback(async () => {
    const el = graphContainerRef.current;
    if (!el) return;
    const { toPng } = await import('html-to-image');
    const dataUrl = await toPng(el, { cacheBust: true });
    const link = document.createElement('a');
    link.href = dataUrl;
    link.download = 'workflow-graph.png';
    link.click();
  }, []);
  const showFilter = agentNames.length >= WORKFLOW_FILTER_MIN_AGENTS;
  const showControls = graph.nodes.length > 0;
  const sliderStep = Math.max(1, Math.round(maxDurationMs / 200));
  return (
    <div>
      <div
        role="tablist"
        aria-label="Workflow view"
        className="flex-center gap-0 workflow-tabs"
      >
        {TABS.map(tab => (
          <button
            key={tab}
            type="button"
            role="tab"
            id={`workflow-tab-${tab}`}
            aria-selected={activeTab === tab}
            aria-controls={`workflow-panel-${tab}`}
            onClick={() => setActiveTab(tab)}
            className="btn-reset workflow-tab"
          >
            {TAB_LABELS[tab]}
          </button>
        ))}
      </div>
      {showFilter && (
        <div className="workflow-filter" role="group" aria-label="Filter agents">
          {agentNames.map(name => {
            const color = agentColor(name, agentNames);
            const active = effectiveSelected.has(name);
            return (
              <button
                key={name}
                type="button"
                className="btn-reset eval-filter-chip workflow-filter__chip mono-xs"
                style={{ '--chip-color': color } as React.CSSProperties}
                data-active={active || undefined}
                aria-pressed={active}
                onClick={() => toggleAgent(name)}
              >
                {name}
              </button>
            );
          })}
          {selectedAgents !== null && (
            <button
              type="button"
              className="btn-reset workflow-filter__reset text-xs text-muted"
              onClick={selectAll}
            >
              All
            </button>
          )}
        </div>
      )}
      {showControls && (
        <div className="workflow-filter__controls" role="group" aria-label="Graph controls">
          <label className="workflow-filter__label">
            Min duration
            <input
              type="range"
              min={0}
              max={maxDurationMs}
              step={sliderStep}
              value={minDurationMs}
              onChange={e => setMinDurationMs(Number(e.target.value))}
              className="workflow-filter__slider"
              aria-label={`Minimum agent duration: ${fmtDuration(minDurationMs)}`}
            />
            <span className="workflow-filter__slider-value mono-xs">
              {minDurationMs > 0 ? `≥ ${fmtDuration(minDurationMs)}` : 'any'}
            </span>
          </label>
          <button
            type="button"
            className="btn-reset eval-filter-chip workflow-filter__chip eval-filter-chip--error"
            data-active={errorsOnly || undefined}
            aria-pressed={errorsOnly}
            onClick={() => setErrorsOnly(v => !v)}
          >
            Errors only
          </button>
          <button
            type="button"
            className="btn-reset eval-filter-chip workflow-filter__chip eval-filter-chip--accent"
            data-active={showCriticalPath || undefined}
            aria-pressed={showCriticalPath}
            onClick={() => setShowCriticalPath(v => !v)}
          >
            Critical path
          </button>
          <button
            type="button"
            className="btn-reset workflow-filter__export mono-xs"
            onClick={() => void handleExport()}
            aria-label="Export graph as PNG"
          >
            Export PNG
          </button>
        </div>
      )}
      <div
        role="tabpanel"
        id="workflow-panel-dag"
        aria-labelledby="workflow-tab-dag"
        hidden={activeTab !== 'dag'}
      >
        <WorkflowGraphView
          graph={graph}
          onNodeClick={onNodeClick}
          height={height}
          selectedAgents={filteredNodeIds}
          criticalPath={criticalPathSet}
          containerRef={graphContainerRef}
        />
      </div>
      <div
        role="tabpanel"
        id="workflow-panel-timeline"
        aria-labelledby="workflow-tab-timeline"
        hidden={activeTab !== 'timeline'}
      >
        <WorkflowTimeline
          turns={evaluation?.turns ?? []}
          handoffs={evaluation?.handoffs ?? []}
          agentNames={agentNames}
          selectedAgents={showFilter ? effectiveSelected : undefined}
        />
      </div>
    </div>
  );
}import { Link } from 'wouter';
import type { CSSProperties } from 'react';
import { formatScore } from '../lib/quality-utils.js';
import type { TriggeredAlert } from '../types.js';
type AlertWithMeta = TriggeredAlert & { metricName?: string };
function SimpleAlertItem({ alert }: { alert: AlertWithMeta }) {
  return (
    <li className="alert-item" data-status={alert.severity}>
      <div className="alert-message">{alert.message}</div>
      <div className="alert-meta text-secondary text-xs">
        {alert.aggregation} = {formatScore(alert.actualValue)} (threshold: {formatScore(alert.threshold)})
      </div>
      {alert.remediationHints && alert.remediationHints.length > 0 && (
        <div className="remediation text-xs">
          Hint: {alert.remediationHints[0]}
        </div>
      )}
    </li>
  );
}
function ThresholdBar({ actual, threshold, direction }: {
  actual: number;
  threshold: number;
  direction: 'above' | 'below';
}) {
  const max = Math.max(actual, threshold) * 1.2 || 1;
  const actualPct = Math.max(0, Math.min((actual / max) * 100, 100));
  const thresholdPct = Math.max(0, Math.min((threshold / max) * 100, 100));
  const isViolating = direction === 'below' ? actual < threshold : actual > threshold;
  return (
    <div className="threshold-bar" aria-label={`Actual: ${formatScore(actual)}, Threshold: ${formatScore(threshold)}`}>
      <div
        className="threshold-bar-fill"
        data-violating={isViolating || undefined}
        style={{ '--bar-fill-width': `${actualPct}%` } as CSSProperties}
      />
      <div
        className="threshold-bar-marker"
        style={{ '--bar-marker-left': `${thresholdPct}%` } as CSSProperties}
        title={`Threshold: ${formatScore(threshold)}`}
      />
    </div>
  );
}
function CompoundAlertCard({ alert }: { alert: AlertWithMeta }) {
  return (
    <li className="alert-item alert-compound" data-status={alert.severity}>
      <div className="alert-message">{alert.message}</div>
      <div className="alert-meta text-secondary text-xs">
        {alert.aggregation} = {formatScore(alert.actualValue)} (threshold: {formatScore(alert.threshold)})
      </div>
      <ThresholdBar
        actual={alert.actualValue}
        threshold={alert.threshold}
        direction={alert.direction}
      />
      {alert.remediationHints && alert.remediationHints.length > 0 && (
        <ol className="remediation-list text-xs">
          {alert.remediationHints.map((hint) => (
            <li key={hint}>{hint}</li>
          ))}
        </ol>
      )}
      {alert.relatedMetrics && alert.relatedMetrics.length > 0 && (
        <div className="alert-related flex-center">
          <span className="text-secondary text-xs">Related:</span>
          {alert.relatedMetrics.map((m) => (
            <Link key={m} href={`/metrics/${m}`} className="alert-metric-link text-xs">
              {m}
            </Link>
          ))}
        </div>
      )}
    </li>
  );
}
const SEVERITY_ORDER: Record<string, number> = { critical: 0, warning: 1, info: 2 };
export function AlertList({ alerts }: { alerts: AlertWithMeta[] }) {
  if (alerts.length === 0) return null;
  const sorted = [...alerts].sort((a, b) =>
    (SEVERITY_ORDER[a.severity] ?? 2) - (SEVERITY_ORDER[b.severity] ?? 2)
  );
  return (
    <ul className="alert-list">
      {sorted.map((alert) =>
        alert.isCompound
          ? <CompoundAlertCard key={alert.message} alert={alert} />
          : <SimpleAlertItem key={alert.message} alert={alert} />
      )}
    </ul>
  );
}import type { CSSProperties } from 'react';
interface BarIndicatorProps {
  value: number;
  color?: string;
  opacity?: number;
  height?: number;
  trackColor?: string;
