    const name = ev.evaluationName;
    if (!byName.has(name)) byName.set(name, []);
    byName.get(name)!.push(ev);
  }
  return (
    <div className="flex-wrap gap-2">
      {[...byName.entries()].map(([name, evs]) => {
        const avg = evs.reduce((s, e) => s + (e.scoreValue ?? 0), 0) / evs.length;
        const card = (
          <div className={`flex-center gap-1-5 surface-elevated eval-overlay-card${traceId ? ' eval-summary-card' : ''}`}>
            <span className="text-xs">{name}</span>
            <ScoreBadge score={avg} metricName={name} label={avg.toFixed(SCORE_CHIP_PRECISION)} />
            <span className="text-muted text-2xs">({evs.length})</span>
          </div>
        );
        if (traceId) {
          return (
            <Link
              key={name}
              href={routes.evaluationDetail(traceId, name)}
              className="link-plain"
            >
              {card}
            </Link>
          );
        }
        return <div key={name}>{card}</div>;
      })}
    </div>
  );
}import { Link } from 'wouter';
import { SCORE_COLORS } from '../lib/quality-utils.js';
import { routes } from '../lib/routes.js';
import { SCORE_CHIP_PRECISION } from '../lib/constants.js';
import { ScoreChip, ColoredChip } from './Chip.js';
import { MetaItem } from './MetaItem.js';
import { SectionBlock } from './SectionBlock.js';
import type { EvalRow } from './EvaluationTable.js';
export function StepScoreChip({ step, score, explanation }: {
  step: string | number;
  score: number;
  explanation?: string;
}) {
  return (
    <ScoreChip score={score} direction="maximize" title={explanation ?? `Step ${step}: ${score.toFixed(SCORE_CHIP_PRECISION)}`}>
      {step}: {score.toFixed(SCORE_CHIP_PRECISION)}
    </ScoreChip>
  );
}
export function ToolVerificationChip({ toolName, toolCorrect, argsCorrect, score }: {
  toolName: string;
  toolCorrect: boolean;
  argsCorrect: boolean;
  score: number;
}) {
  const ok = toolCorrect && argsCorrect;
  const color = ok ? SCORE_COLORS.excellent : SCORE_COLORS.failing;
  return (
    <ColoredChip
      color={color}
      title={`tool: ${toolCorrect ? 'correct' : 'wrong'}, args: ${argsCorrect ? 'correct' : 'wrong'}, score: ${score.toFixed(SCORE_CHIP_PRECISION)}`}
    >
      {toolName} {score.toFixed(SCORE_CHIP_PRECISION)}
    </ColoredChip>
  );
}
export function EvaluationExpandedRow({ row }: { row: EvalRow }) {
  const meta = [
    { label: 'Evaluator Type', value: row.evaluatorType },
    { label: 'Trace ID', value: row.traceId },
    { label: 'Span ID', value: row.spanId },
    { label: 'Session ID', value: row.sessionId },
    { label: 'Agent', value: row.agentName },
    { label: 'Trajectory Length', value: row.trajectoryLength },
  ].filter(m => m.value != null);
  const hasDetail = !!row.explanation || meta.length > 0 ||
    (row.stepScores != null && row.stepScores.length > 0) ||
    (row.toolVerifications != null && row.toolVerifications.length > 0);
  return (
    <div className="eval-expanded-content">
      {row.explanation && (
        <SectionBlock label="Explanation">
          <div className="text-xs text-primary leading-normal">
            {row.explanation}
          </div>
        </SectionBlock>
      )}
      {meta.length > 0 && (
        <div className="mb-3 flex-wrap gap-4">
          {meta.map(m => <MetaItem key={m.label} label={m.label} value={m.value} />)}
        </div>
      )}
      {row.stepScores && row.stepScores.length > 0 && (
        <SectionBlock label="Step Scores">
          <div className="flex-wrap gap-1-5">
            {row.stepScores.map(s => (
              <StepScoreChip key={`${s.step}`} step={s.step} score={s.score} explanation={s.explanation} />
            ))}
          </div>
        </SectionBlock>
      )}
      {row.toolVerifications && row.toolVerifications.length > 0 && (
        <SectionBlock label="Tool Verifications">
          <div className="flex-wrap gap-1-5">
            {row.toolVerifications.map((tv) => (
              <ToolVerificationChip
                key={`${tv.toolName}-${tv.score}`}
                toolName={tv.toolName}
                toolCorrect={tv.toolCorrect}
                argsCorrect={tv.argsCorrect}
                score={tv.score}
              />
            ))}
          </div>
        </SectionBlock>
      )}
      {}
      {(!!row.traceId || !!row.sessionId) && (
        <div className="d-flex gap-4 mt-3 border-t pt-3">
          {row.traceId && (
            <Link href={routes.evaluationDetail(row.traceId)} className="back-link inline-flex-center mb-0">
              View full evaluation detail &rarr;
            </Link>
          )}
          {row.sessionId ? (
            <Link href={routes.session(row.sessionId)} className="back-link inline-flex-center mb-0">
              View trace spans &rarr;
            </Link>
          ) : row.traceId ? (
            <Link href={routes.trace(row.traceId)} className="back-link inline-flex-center mb-0">
              View trace spans &rarr;
            </Link>
          ) : null}
        </div>
      )}
      {!hasDetail && !row.traceId && !row.sessionId && (
        <div className="text-muted text-xs">
          No additional detail available.
        </div>
      )}
    </div>
  );
}import { useState, Fragment } from 'react';
import type { EvaluationResult } from '../types.js';
import {
  createColumnHelper,
  useReactTable,
  getCoreRowModel,
  getSortedRowModel,
  getFilteredRowModel,
  getExpandedRowModel,
  flexRender,
  type SortingState,
  type ColumnFiltersState,
  type ExpandedState,
  type SortingFn,
  type FilterFn,
} from '@tanstack/react-table';
import type { CSSProperties } from 'react';
import {
  labelToOrdinal,
  ordinalToCategory,
  truncateText,
  formatScore,
  SCORE_COLORS,
  type LabelFilterCategory,
} from '../lib/quality-utils.js';
import { EVAL_TABLE_EXPAND_COL_SIZE } from '../lib/constants.js';
import { EvaluationExpandedRow } from './EvaluationExpandedRow.js';
import { TimestampCell } from './TimestampCell.js';
import { ExpandChevron } from './ExpandChevron.js';
import { ColoredChip } from './Chip.js';
import { ScoreBadge } from './ScoreBadge.js';
export interface EvalRow {
  score: number | null;
  explanation?: string;
  traceId?: string;
  timestamp?: string;
  evaluator?: string;
  label?: string;
  evaluatorType?: string;
  spanId?: string;
  sessionId?: string;
  agentName?: string;
  trajectoryLength?: number;
  stepScores?: Array<{ step: string | number; score: number; explanation?: string }>;
  toolVerifications?: Array<{ toolName: string; toolCorrect: boolean; argsCorrect: boolean; score: number }>;
}
const CATEGORY_COLORS: Record<LabelFilterCategory, string> = {
  Pass: SCORE_COLORS.excellent,
  Review: SCORE_COLORS.adequate,
  Fail: SCORE_COLORS.failing,
};
const labelSortFn: SortingFn<EvalRow> = (rowA, rowB) => {
  const a = labelToOrdinal(rowA.original.label ?? 'unknown').ordinal;
  const b = labelToOrdinal(rowB.original.label ?? 'unknown').ordinal;
  return a - b;
};
const categoryFilterFn: FilterFn<EvalRow> = (row, _id, filterValue: LabelFilterCategory[]) => {
  if (filterValue.length === 0) return true;
  const category = ordinalToCategory(labelToOrdinal(row.original.label ?? 'unknown').ordinal);
  return filterValue.includes(category);
};
const columnHelper = createColumnHelper<EvalRow>();
const columns = [
  columnHelper.display({
    id: 'expand',
    header: '',
    cell: ({ row }) => (
      <button
        type="button"
        className="cursor-pointer btn-reset btn-expand"
        onClick={row.getToggleExpandedHandler()}
        aria-label={row.getIsExpanded() ? 'Collapse row' : 'Expand row'}
      >
        <ExpandChevron expanded={row.getIsExpanded()} className="text-secondary text-xs" />
      </button>
    ),
    size: EVAL_TABLE_EXPAND_COL_SIZE,
  }),
  columnHelper.accessor('score', {
    header: 'Score',
    cell: (info) => {
      const row = info.row.original;
      return (
        <ScoreBadge
          score={info.getValue()}
          metricName="score"
          label={formatScore(info.getValue())}
          evaluator={row.evaluator}
          evaluatorType={row.evaluatorType}
          explanation={row.explanation}
          traceId={row.traceId}
        />
      );
    },
    sortingFn: 'basic',
  }),
  columnHelper.accessor('label', {
    header: 'Label',
    cell: (info) => {
      const label = info.getValue() ?? 'unknown';
      const { category } = labelToOrdinal(label);
      return (
        <ColoredChip color={CATEGORY_COLORS[category]} className="font-medium">
          {label}
        </ColoredChip>
      );
    },
    sortingFn: labelSortFn,
    filterFn: categoryFilterFn,
  }),
  columnHelper.display({
    id: 'category',
    header: 'Category',
    cell: (info) => {
      const label = info.row.original.label ?? 'unknown';
      const category = ordinalToCategory(labelToOrdinal(label).ordinal);
      return (
        <ColoredChip color={CATEGORY_COLORS[category]} className="font-semibold">
          {category}
        </ColoredChip>
      );
    },
  }),
  columnHelper.accessor('explanation', {
    header: 'Explanation',
    cell: (info) => {
      const text = info.getValue() ?? '-';
      return (
        <span className="explanation truncate" title={text}>
          {truncateText(text, 60)}
        </span>
      );
    },
    enableSorting: false,
  }),
  columnHelper.accessor('evaluator', {
    header: 'Evaluator',
    cell: (info) => (
      <span className="mono-xs">
        {info.getValue() ?? '-'}
      </span>
    ),
    enableSorting: false,
  }),
  columnHelper.accessor('timestamp', {
    header: 'Timestamp',
    cell: (info) => {
      const ts = info.getValue();
      if (!ts) return '-';
      return (
        <TimestampCell timestamp={ts} />
      );
    },
    sortingFn: 'datetime',
  }),
];
export function evalToRow(e: EvaluationResult): EvalRow {
  return {
    score: typeof e.scoreValue === 'number' ? e.scoreValue : null,
    explanation: e.explanation,
    traceId: e.traceId,
    timestamp: String(e.timestamp),
    evaluator: e.evaluator,
    label: e.scoreLabel,
    evaluatorType: e.evaluatorType,
    spanId: e.spanId,
    sessionId: e.sessionId,
    agentName: e.agentName,
    trajectoryLength: e.trajectoryLength,
    stepScores: e.stepScores,
    toolVerifications: e.toolVerifications,
  };
}
export function EvaluationTable({ evaluations }: { evaluations: EvalRow[] }) {
  'use no memo';
  const [sorting, setSorting] = useState<SortingState>([]);
  const [columnFilters, setColumnFilters] = useState<ColumnFiltersState>([]);
  const [expanded, setExpanded] = useState<ExpandedState>({});
  const table = useReactTable({
    data: evaluations,
    columns,
    state: { sorting, columnFilters, expanded },
    onSortingChange: setSorting,
    onColumnFiltersChange: setColumnFilters,
    onExpandedChange: setExpanded,
    getRowCanExpand: () => true,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    getExpandedRowModel: getExpandedRowModel(),
  });
  const activeCategories: LabelFilterCategory[] =
    (columnFilters.find(f => f.id === 'label')?.value as LabelFilterCategory[] | undefined) ?? [];
  const toggleCategory = (cat: LabelFilterCategory) => {
    const next = activeCategories.includes(cat)
      ? activeCategories.filter((c) => c !== cat)
      : [...activeCategories, cat];
    setColumnFilters(next.length > 0 ? [{ id: 'label', value: next }] : []);
  };
  const sortDir = (colId: string): 'ascending' | 'descending' | 'none' => {
    const s = sorting.find((entry) => entry.id === colId);
    if (!s) return 'none';
    return s.desc ? 'descending' : 'ascending';
  };
  return (
    <div>
      <div className="d-flex mb-3 gap-1-5">
        {(['Pass', 'Review', 'Fail'] as const).map((cat) => {
          const active = activeCategories.includes(cat);
          return (
            <button
              key={cat}
              type="button"
              onClick={() => toggleCategory(cat)}
              className="eval-filter-chip text-xs font-semibold cursor-pointer"
              style={{ '--chip-color': CATEGORY_COLORS[cat] } as CSSProperties}
              data-active={active || undefined}
            >
              {cat}
            </button>
          );
        })}
      </div>
      <table className="data-table eval-table">
        <thead>
          {table.getHeaderGroups().map((hg) => (
            <tr key={hg.id}>
              {hg.headers.map((header) => {
                const canSort = header.column.getCanSort();
                return (
                  <th
                    key={header.id}
                    onClick={canSort ? header.column.getToggleSortingHandler() : undefined}
                    className={`select-none${canSort ? ' cursor-pointer' : ''}`}
                    aria-sort={canSort ? sortDir(header.id) : undefined}
                  >
                    {flexRender(header.column.columnDef.header, header.getContext())}
                    {canSort && (
                      <span className="ml-1 text-2xs">
                        {{ asc: ' ^', desc: ' v' }[header.column.getIsSorted() as string] ?? ''}
                      </span>
                    )}
                  </th>
                );
              })}
            </tr>
          ))}
        </thead>
        <tbody>
          {table.getRowModel().rows.map((row) => (
            <Fragment key={row.id}>
              <tr className={row.getIsExpanded() ? 'eval-row-expanded' : ''}>
                {row.getVisibleCells().map((cell) => (
                  <td key={cell.id}>
                    {flexRender(cell.column.columnDef.cell, cell.getContext())}
                  </td>
                ))}
              </tr>
              {row.getIsExpanded() && (
                <tr className="eval-expanded-panel">
                  <td colSpan={row.getVisibleCells().length}>
                    <EvaluationExpandedRow row={row.original} />
                  </td>
                </tr>
              )}
            </Fragment>
          ))}
          {table.getRowModel().rows.length === 0 && (
            <tr>
              <td colSpan={table.getVisibleLeafColumns().length} className="text-muted text-center p-4">
                No evaluations match the current filter.
              </td>
            </tr>
          )}
        </tbody>
      </table>
    </div>
  );
}import { CHEVRON_RIGHT } from '../lib/symbols.js';
export function ExpandChevron({ expanded, className }: { expanded: boolean; className?: string }) {
  return (
    <span
      className={`expand-chevron${expanded ? ' expand-chevron--open' : ''}${className ? ` ${className}` : ''}`}
      aria-hidden="true"
    >
