import { fmtDuration, plural } from '../lib/quality-utils.js';
import { OTEL_STATUS_ERROR_CODE, SPAN_TREE_INDENT, SPAN_TREE_BASE_PADDING } from '../lib/constants.js';
import { EmptyState } from './EmptyState.js';
interface SpanNode {
  spanId: string;
  name: string;
  durationMs?: number;
  status?: { code: number; message?: string };
  attributes?: Record<string, unknown>;
  children: SpanNode[];
  evalCount: number;
}
interface SpanTreeProps {
  spans: Array<{
    spanId: string;
    name: string;
    durationMs?: number;
    status?: { code: number; message?: string };
    attributes?: Record<string, unknown>;
    parentSpanId?: string;
  }>;
  evalsBySpan: Map<string, number>;
  maxDuration: number;
}
function buildTree(
  spans: SpanTreeProps['spans'],
  evalsBySpan: Map<string, number>,
): SpanNode[] {
  const nodeMap = new Map<string, SpanNode>();
  const roots: SpanNode[] = [];
  for (const s of spans) {
    nodeMap.set(s.spanId, {
      spanId: s.spanId,
      name: s.name,
      durationMs: s.durationMs,
      status: s.status,
      attributes: s.attributes,
      children: [],
      evalCount: evalsBySpan.get(s.spanId) ?? 0,
    });
  }
  for (const s of spans) {
    const node = nodeMap.get(s.spanId)!;
    const parentId = s.parentSpanId;
    if (parentId && nodeMap.has(parentId)) {
      nodeMap.get(parentId)!.children.push(node);
    } else {
      roots.push(node);
    }
  }
  return roots;
}
const STATUS_ICONS: Record<number, string> = {
  0: '',      // UNSET
  1: '\u2713',
  2: '\u2717',
};
function SpanRow({ node, depth, maxDuration }: { node: SpanNode; depth: number; maxDuration: number }) {
  const barPct = maxDuration > 0 && node.durationMs ? Math.min((node.durationMs / maxDuration) * 100, 100) : 0;
  const statusCode = node.status?.code ?? 0;
  const isError = statusCode === OTEL_STATUS_ERROR_CODE;
  const barStyle: CSSProperties = {
    '--span-bar-width': `${barPct}%`,
    '--span-bar-min-width': barPct > 0 ? 'var(--space-0-5)' : '0',
  } as CSSProperties;
  return (
    <>
      <div
        className="flex-center gap-2 border-b span-row"
        style={{ '--span-row-indent': `${depth * SPAN_TREE_INDENT + SPAN_TREE_BASE_PADDING}px` } as CSSProperties}
      >
        <span className="text-base span-status-icon" data-error={isError || undefined}>
          {STATUS_ICONS[statusCode]}
        </span>
        <div className="flex-1">
          <div className="text-xs font-medium">{node.name}</div>
          <div className="flex-center gap-2">
            <div className="flex-1 bar-track">
              <div className="span-bar" data-error={isError || undefined} style={barStyle} />
            </div>
            {node.durationMs != null && (
              <span className="mono-xs text-secondary nowrap">
                {fmtDuration(node.durationMs, 2)}
              </span>
            )}
          </div>
        </div>
        {node.evalCount > 0 && (
          <span className="text-2xs chip font-semibold chip-accent">
            {plural(node.evalCount, 'eval')}
          </span>
        )}
      </div>
      {node.children.map(child => (
        <SpanRow key={child.spanId} node={child} depth={depth + 1} maxDuration={maxDuration} />
      ))}
    </>
  );
}
export function SpanTree({ spans, evalsBySpan, maxDuration }: SpanTreeProps) {
  const roots = buildTree(spans, evalsBySpan);
  if (roots.length === 0) {
    return <EmptyState message="No spans found for this trace." />;
  }
  return (
    <div>
      {roots.map(node => (
        <SpanRow key={node.spanId} node={node} depth={0} maxDuration={maxDuration} />
      ))}
    </div>
  );
}import { memo } from 'react';
interface SparklineProps {
  data: (number | null)[];
  width?: number;
  height?: number;
  color?: string;
  label?: string;
}
function SparklineInner({ data, width = 80, height = 24, color = 'var(--text-secondary)', label }: SparklineProps) {
  const values = data.filter((v): v is number => v !== null && Number.isFinite(v));
  if (values.length < 2) return null;
  const min = Math.min(...values);
  const max = Math.max(...values);
  const range = max - min || 1;
  const pad = 2;
  const xDenom = data.length > 1 ? data.length - 1 : 1;
  const points = data
    .map((v, i) => {
      if (v === null || !Number.isFinite(v)) return null;
      const x = pad + (i / xDenom) * (width - pad * 2);
      const y = pad + (1 - (v - min) / range) * (height - pad * 2);
      return `${x},${y}`;
    })
    .filter((p): p is string => p !== null)
    .join(' ');
  return (
    <svg
      width={width}
      height={height}
      viewBox={`0 0 ${width} ${height}`}
      role="img"
      aria-label={label ?? 'Score trend sparkline'}
      className="d-block"
    >
      <polyline
        points={points}
        fill="none"
        stroke={color}
        strokeWidth={1.5}
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}
export const Sparkline = memo(SparklineInner);import { useState, useCallback, useRef, useEffect, type ReactNode, type CSSProperties } from 'react';
interface SplitPaneProps {
  left: ReactNode;
  right: ReactNode;
  initialSplit?: number;
  minPct?: number;
  maxPct?: number;
}
export function SplitPane({ left, right, initialSplit = 50, minPct = 25, maxPct = 75 }: SplitPaneProps) {
  const [splitPct, setSplitPct] = useState(initialSplit);
  const containerRef = useRef<HTMLDivElement>(null);
  const dragging = useRef(false);
  const onMouseDown = useCallback(() => { dragging.current = true; }, []);
  useEffect(() => {
    function onMouseMove(e: MouseEvent) {
      if (!dragging.current || !containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      const pct = ((e.clientX - rect.left) / rect.width) * 100;
      setSplitPct(Math.max(minPct, Math.min(maxPct, pct)));
    }
    function onMouseUp() { dragging.current = false; }
    document.addEventListener('mousemove', onMouseMove);
    document.addEventListener('mouseup', onMouseUp);
    return () => {
      dragging.current = false;
      document.removeEventListener('mousemove', onMouseMove);
      document.removeEventListener('mouseup', onMouseUp);
    };
  }, [minPct, maxPct]);
  return (
    <div ref={containerRef} className="d-flex w-full split-pane">
      <div className="split-pane-panel" style={{ '--split-width': `${splitPct}%` } as CSSProperties}>{left}</div>
      <div
        className="shrink-0 split-pane-divider" role="separator"
        aria-orientation="vertical"
        aria-valuenow={Math.round(splitPct)}
        aria-valuemin={minPct}
        aria-valuemax={maxPct}
        aria-label="Resize panes"
        tabIndex={0}
        onMouseDown={onMouseDown}
        onKeyDown={(e) => {
          if (e.key === 'ArrowLeft') { e.preventDefault(); setSplitPct(p => Math.max(minPct, p - 2)); }
          if (e.key === 'ArrowRight') { e.preventDefault(); setSplitPct(p => Math.min(maxPct, p + 2)); }
        }}
      />
      <div className="split-pane-panel" style={{ '--split-width': `${100 - splitPct}%` } as CSSProperties}>{right}</div>
    </div>
  );
}import type { ReactNode } from 'react';
