  const shown = items.slice(0, max);
  const remainder = (total ?? items.length) - shown.length;
  return (
    <>
      {shown.map(renderItem)}
      {remainder > 0 && (
        <div className="text-muted text-xs mt-1">+{remainder} more</div>
      )}
    </>
  );
