  critical?: boolean;
  onActivate?: () => void;
}
interface ClusterNodeData {
  clusterId: string;
  memberCount: number;
  hasError: boolean;
  avgScore: number | null;
  onActivate?: () => void;
}
function activationKeyHandler(onActivate: (() => void) | undefined) {
  if (!onActivate) return undefined;
  return (event: React.KeyboardEvent) => {
    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      onActivate();
    }
  };
}
function isWorkflowNode(value: unknown): value is WorkflowNodeWithMeta {
  if (!value || typeof value !== 'object') return false;
  const v = value as Record<string, unknown>;
  return (
    typeof v['id'] === 'string' &&
    typeof v['label'] === 'string' &&
    typeof v['toolCallCount'] === 'number' &&
    typeof v['turnCount'] === 'number' &&
    typeof v['durationMs'] === 'number' &&
    typeof v['hasError'] === 'boolean'
  );
}
function isClusterNodeData(value: unknown): value is ClusterNodeData {
  if (!value || typeof value !== 'object') return false;
  const v = value as Record<string, unknown>;
  return (
    typeof v['clusterId'] === 'string' &&
    typeof v['memberCount'] === 'number' &&
    typeof v['hasError'] === 'boolean'
  );
}
function buildNodeDataMap(nodes: WorkflowNode[]): Map<string, WorkflowNode> {
  const map = new Map<string, WorkflowNode>();
  for (const n of nodes) map.set(n.id, n);
  return map;
}
const CLUSTER_NODE_PREFIX = '__cluster__';
function clusterNodeId(clusterId: string): string {
  return `${CLUSTER_NODE_PREFIX}${clusterId}`;
}
function isClusterNodeId(id: string): boolean {
  return id.startsWith(CLUSTER_NODE_PREFIX);
}
export function applyClusterCollapse(
  nodes: WorkflowNode[],
  edges: WorkflowEdge[],
  collapsedClusters: ReadonlySet<string>,
): { nodes: WorkflowNode[]; edges: WorkflowEdge[] } {
  if (collapsedClusters.size === 0) return { nodes, edges };
  const nodeClusterMap = new Map<string, string>();
  for (const n of nodes) {
    if (n.clusterId && collapsedClusters.has(n.clusterId)) {
      nodeClusterMap.set(n.id, n.clusterId);
    }
  }
  const nodeDataMap = buildNodeDataMap(nodes);
  const clusterableNodes = [...nodeClusterMap.keys()].map(id => nodeDataMap.get(id)).filter((n): n is WorkflowNode => n != null);
  const clusterMembers = groupBy(clusterableNodes, n => nodeClusterMap.get(n.id));
  const syntheticNodes: WorkflowNode[] = [];
  for (const [cId, members] of clusterMembers) {
    const scores = members.map(m => m.evaluationScore).filter((s): s is number => s !== null);
    const avgScore = scores.length > 0 ? scores.reduce((a, b) => a + b, 0) / scores.length : null;
    syntheticNodes.push({
      id: clusterNodeId(cId),
      label: `[Cluster] ${cId}`,
      evaluationScore: avgScore,
      toolCallCount: members.reduce((s, m) => s + m.toolCallCount, 0),
      totalTokens: members.reduce((s, m) => s + (m.totalTokens ?? 0), 0),
      durationMs: members.reduce((s, m) => s + m.durationMs, 0),
      turnCount: members.reduce((s, m) => s + m.turnCount, 0),
      hasError: members.some(m => m.hasError),
      clusterId: cId,
      clusterMemberCount: members.length,
    });
  }
  const outNodes = [
    ...nodes.filter(n => !nodeClusterMap.has(n.id)),
    ...syntheticNodes,
  ];
  const resolveId = (id: string): string => {
    const cId = nodeClusterMap.get(id);
    return cId ? clusterNodeId(cId) : id;
  };
  const seenEdgeKeys = new Set<string>();
  const outEdges: WorkflowEdge[] = [];
  for (const e of edges) {
    const src = resolveId(e.source);
    const tgt = resolveId(e.target);
    if (src === tgt) continue;
    const key = `${src}->${tgt}`;
    if (seenEdgeKeys.has(key)) continue;
    seenEdgeKeys.add(key);
    outEdges.push({ ...e, id: key, source: src, target: tgt });
  }
  return { nodes: outNodes, edges: outEdges };
}
export function extractClusterIds(nodes: WorkflowNode[]): string[] {
  const seen = new Set<string>();
  for (const n of nodes) {
    if (n.clusterId) seen.add(n.clusterId);
  }
  return [...seen].sort();
}
async function computeLayout(
  nodes: WorkflowNode[],
  edges: WorkflowEdge[],
  selectedAgents?: ReadonlySet<string>,
  criticalPath?: ReadonlySet<string>,
  onNodeActivate?: (nodeId: string) => void,
): Promise<{ nodes: Node[]; edges: Edge[] }> {
  const nodeDataMap = buildNodeDataMap(nodes);
  const elkGraph = {
    id: 'root',
    layoutOptions: ELK_OPTIONS,
    children: nodes.map(n => {
      const isCluster = isClusterNodeId(n.id);
      return {
        id: n.id,
        width: isCluster ? CLUSTER_NODE_WIDTH : NODE_WIDTH,
        height: isCluster ? CLUSTER_NODE_HEIGHT : NODE_HEIGHT,
      };
    }),
    edges: edges.map(e => ({ id: e.id, sources: [e.source], targets: [e.target] })),
  };
  const layout = await elk.layout(elkGraph);
  const rfNodes: Node[] = (layout.children ?? [])
    .filter(elkNode => nodeDataMap.has(elkNode.id))
    .map(elkNode => {
      const workflowNode = nodeDataMap.get(elkNode.id)!;
      const dimmed = selectedAgents != null && !selectedAgents.has(elkNode.id);
      const critical = criticalPath?.has(elkNode.id) ?? false;
      const isCluster = isClusterNodeId(elkNode.id);
      const onActivate = onNodeActivate ? () => onNodeActivate(elkNode.id) : undefined;
      if (isCluster) {
        const avgScore = workflowNode.evaluationScore;
        const data: ClusterNodeData = {
          clusterId: workflowNode.clusterId ?? elkNode.id,
          memberCount: workflowNode.clusterMemberCount ?? 0,
          hasError: workflowNode.hasError,
          avgScore,
          onActivate,
        };
        return {
          id: elkNode.id,
          position: { x: elkNode.x ?? 0, y: elkNode.y ?? 0 },
          data: data as unknown as Record<string, unknown>,
          type: 'clusterNode',
        };
      }
      return {
        id: elkNode.id,
        position: { x: elkNode.x ?? 0, y: elkNode.y ?? 0 },
        data: { ...workflowNode, dimmed, critical, onActivate },
        type: 'agentNode',
      };
    });
  const rfEdges: Edge[] = edges.map(e => ({
    id: e.id,
    source: e.source,
    target: e.target,
    label: e.label,
  }));
  return { nodes: rfNodes, edges: rfEdges };
}
const AgentNodeComponent = memo(function AgentNodeComponent({ data }: NodeProps) {
  if (!isWorkflowNode(data)) return null;
  const d = data;
  const band = getScoreBand(d.evaluationScore);
  const onActivate = d.dimmed ? undefined : d.onActivate;
  const nodeClass = [
    'workflow-node',
    band?.className,
    d.dimmed && 'workflow-node--dimmed',
    d.critical && 'workflow-node--critical',
  ].filter(Boolean).join(' ');
  return (
    <div
      className={nodeClass}
      role={onActivate ? 'button' : 'group'}
      tabIndex={onActivate ? 0 : undefined}
      onKeyDown={activationKeyHandler(onActivate)}
      aria-label={`Agent: ${d.label}, Score: ${d.evaluationScore ?? 'N/A'}`}
    >
      <div className="workflow-node__label">{d.label}</div>
      {band && (
        <div className="workflow-node__score">
          <span>{band.label}</span>: {d.evaluationScore?.toFixed(SCORE_CHIP_PRECISION)}
        </div>
      )}
      <div className="workflow-node__meta">
        <span>{d.toolCallCount} tools</span> | <span>{d.turnCount} turns</span>
        {d.totalTokens != null && <span> | {(d.totalTokens / 1000).toFixed(1)}K tok</span>}
      </div>
      <div className="workflow-node__duration">
        {fmtDuration(d.durationMs)}
      </div>
      {d.hasError && <div className="workflow-node__error">Error</div>}
      <Handle type="target" position={Position.Top} />
      <Handle type="source" position={Position.Bottom} />
    </div>
  );
});
const ClusterNodeComponent = memo(function ClusterNodeComponent({ data }: NodeProps) {
  if (!isClusterNodeData(data)) return null;
  const d = data;
  const band = getScoreBand(d.avgScore);
  const nodeClass = [
    'workflow-cluster-node',
    band?.className,
    d.hasError && 'workflow-cluster-node--error',
  ].filter(Boolean).join(' ');
  return (
    <div
      className={nodeClass}
      role={d.onActivate ? 'button' : 'group'}
      tabIndex={d.onActivate ? 0 : undefined}
      onKeyDown={activationKeyHandler(d.onActivate)}
      aria-label={`Cluster: ${d.clusterId}, ${d.memberCount} agents`}
    >
      <div className="workflow-cluster-node__label">{d.clusterId}</div>
      <div className="workflow-cluster-node__meta">
        {d.memberCount} agents
        {d.avgScore !== null && (
          <span> · avg {d.avgScore.toFixed(SCORE_CHIP_PRECISION)}</span>
        )}
      </div>
      {d.hasError && <div className="workflow-node__error">Error</div>}
      <Handle type="target" position={Position.Top} />
      <Handle type="source" position={Position.Bottom} />
    </div>
  );
});
const NODE_TYPES = { agentNode: AgentNodeComponent, clusterNode: ClusterNodeComponent };
interface WorkflowGraphProps {
  graph: WorkflowGraph;
  onNodeClick?: (nodeId: string) => void;
  height?: number;
  selectedAgents?: ReadonlySet<string>;
  criticalPath?: ReadonlySet<string>;
  containerRef?: React.RefObject<HTMLDivElement | null>;
}
export function WorkflowGraphView({ graph, onNodeClick, height = 600, selectedAgents, criticalPath, containerRef }: WorkflowGraphProps) {
  const containerStyle = { '--workflow-graph-height': `${height}px` } as React.CSSProperties;
  const [nodes, setNodes, onNodesChange] = useNodesState<Node>([]);
  const [edges, setEdges, onEdgesChange] = useEdgesState<Edge>([]);
  const [layoutError, setLayoutError] = useState<string | null>(null);
  const [collapsedClusters, setCollapsedClusters] = useState<ReadonlySet<string>>(new Set());
  const onNodeClickRef = useRef(onNodeClick);
  useEffect(() => {
    onNodeClickRef.current = onNodeClick;
  }, [onNodeClick]);
  const activateNode = useCallback((nodeId: string) => {
    onNodeClickRef.current?.(nodeId);
  }, []);
  const hasNodeClick = onNodeClick != null;
  const clusterIds = extractClusterIds(graph.nodes);
  const toggleCluster = useCallback((clusterId: string) => {
    setCollapsedClusters(prev => {
      const next = new Set(prev);
      if (next.has(clusterId)) {
        next.delete(clusterId);
      } else {
        next.add(clusterId);
      }
      return next;
    });
  }, []);
  useEffect(() => {
    if (graph.nodes.length === 0) return;
    let cancelled = false;
    const { nodes: visibleNodes, edges: visibleEdges } = applyClusterCollapse(
      graph.nodes,
      graph.edges,
      collapsedClusters,
    );
    computeLayout(visibleNodes, visibleEdges, selectedAgents, criticalPath, hasNodeClick ? activateNode : undefined)
      .then(({ nodes: rfNodes, edges: rfEdges }) => {
        if (!cancelled) {
          setLayoutError(null);
          setNodes(rfNodes);
          setEdges(rfEdges);
        }
      })
      .catch(err => {
        if (!cancelled) {
          setLayoutError(err instanceof Error ? err.message : 'Layout computation failed');
        }
      });
    return () => { cancelled = true; };
  }, [graph.nodes, graph.edges, selectedAgents, criticalPath, collapsedClusters, hasNodeClick, activateNode]);
  const handleNodeClick = useCallback((_: React.MouseEvent, node: Node) => {
    onNodeClick?.(node.id);
  }, [onNodeClick]);
  if (graph.nodes.length > MAX_ELK_NODES) {
    return (
      <div ref={containerRef} className="workflow-graph-container" style={containerStyle} role="img" aria-label="Agent workflow graph">
        <div className="workflow-oversize text-secondary text-xs">
          <div className="workflow-oversize__heading">
            Graph too large to render ({graph.nodes.length} agents)
          </div>
          <div className="workflow-oversize__note text-muted">
            ELK layout is skipped for graphs with more than {MAX_ELK_NODES} nodes.
          </div>
          <ul className="workflow-oversize__list">
            {graph.nodes.map(n => (
              <li key={n.id} className="mono-xs mb-1">
                {n.label} — {n.turnCount} turns, {n.toolCallCount} tools
                {n.hasError && <span className="text-warning"> (error)</span>}
              </li>
            ))}
          </ul>
        </div>
      </div>
    );
  }
  if (graph.workflowShape === 'single_agent' && graph.nodes.length <= 1) {
    const node = graph.nodes[0];
    return (
      <div ref={containerRef} className="workflow-graph-container" style={containerStyle} role="img" aria-label="Agent workflow graph">
        <div className="workflow-fallback">
          {node ? (
            <>
              <div className="workflow-fallback__title">{node.label}</div>
              <div className="workflow-fallback__subtitle">
                {node.turnCount} turns | {node.toolCallCount} tools
              </div>
            </>
          ) : (
            <div className="workflow-fallback__empty">No agent data</div>
          )}
        </div>
      </div>
    );
  }
  if (layoutError) {
    return (
      <div ref={containerRef} className="workflow-graph-container" style={containerStyle} role="img" aria-label="Agent workflow graph">
        <div className="error-state workflow-fallback">
          Failed to compute workflow layout: {layoutError}
        </div>
      </div>
    );
  }
  const showMiniMap = graph.nodes.length >= MINIMAP_THRESHOLD;
  return (
    <div ref={containerRef} className="workflow-graph-container" style={containerStyle} role="img" aria-label="Agent workflow graph">
      {clusterIds.length > 0 && (
        <div className="workflow-cluster-controls" role="group" aria-label="Cluster toggles">
          {clusterIds.map(cId => (
            <button
              key={cId}
              type="button"
              className={`workflow-cluster-toggle${collapsedClusters.has(cId) ? ' workflow-cluster-toggle--collapsed' : ''}`}
              onClick={() => toggleCluster(cId)}
              aria-pressed={collapsedClusters.has(cId)}
            >
              {collapsedClusters.has(cId) ? '▶' : '▼'} {cId}
            </button>
          ))}
        </div>
      )}
      <ReactFlow
        nodes={nodes}
        edges={edges}
        onNodesChange={onNodesChange}
        onEdgesChange={onEdgesChange}
        onNodeClick={handleNodeClick}
        nodeTypes={NODE_TYPES}
        nodesFocusable={false}
        fitView
      >
        <Controls />
        <Background />
        {showMiniMap && <MiniMap pannable zoomable />}
      </ReactFlow>
    </div>
  );
}import React from 'react';
import { scoreColor, agentColor } from '../lib/quality-utils.js';
import { EmptyState } from './EmptyState.js';
import type { TurnLevelResult, HandoffEvaluation } from '../types.js';
import { SCORE_CHIP_PRECISION } from '../lib/constants.js';
const LANE_HEIGHT = 64;
const LANE_PADDING_TOP = 12;
const TURN_BLOCK_HEIGHT = 32;
const TURN_BLOCK_MIN_WIDTH = 40;
const TURN_BLOCK_GAP = 6;
const TURN_BLOCK_STRIDE = TURN_BLOCK_MIN_WIDTH + TURN_BLOCK_GAP;
const LANE_CENTER_OFFSET = LANE_PADDING_TOP + TURN_BLOCK_HEIGHT / 2;
const LABEL_WIDTH = 120;
const HANDOFF_MARKER_RADIUS = 7;
const HEADER_HEIGHT = 28;
const MAX_VISIBLE_TURNS = 200;
interface LaneSegment {
  agentName: string;
  turns: TurnLevelResult[];
  laneIndex: number;
}
function buildLanes(
  turns: TurnLevelResult[],
  agentNames: string[],
): LaneSegment[] {
  return agentNames.map((name, laneIndex) => ({
    agentName: name,
    turns: turns.filter(t => (t.agentName ?? 'unknown') === name),
    laneIndex,
  }));
}
function findHandoffTurnIndex(
  handoff: HandoffEvaluation,
  turns: TurnLevelResult[],
): number | null {
  let sawSource = false;
  for (const t of turns) {
    const agent = t.agentName ?? 'unknown';
    if (agent === handoff.sourceAgent) sawSource = true;
    if (sawSource && agent === handoff.targetAgent) return t.turnIndex;
  }
  return null;
}
interface TurnBlockProps {
  turn: TurnLevelResult;
  color: string;
  width: number;
  x: number;
  y: number;
}
function TurnBlock({ turn, color, width, x, y }: TurnBlockProps) {
  const barColor = scoreColor(turn.relevance);
  const label = `Turn ${turn.turnIndex}: relevance ${turn.relevance.toFixed(SCORE_CHIP_PRECISION)}, progress ${(turn.taskProgress * 100).toFixed(0)}%${turn.hasError ? ', error' : ''}`;
  return (
    <g transform={`translate(${x},${y})`} role="img" aria-label={label}>
      <rect
        width={width}
        height={TURN_BLOCK_HEIGHT}
        rx={4}
        fill={color}
        fillOpacity={0.15}
        stroke={color}
        strokeWidth={1.5}
      />
      <rect
        width={Math.max(2, width * turn.relevance)}
        height={4}
        rx={2}
        fill={barColor}
        fillOpacity={0.85}
      />
      {turn.hasError && (
        <rect
          x={width - 6}
          width={4}
          height={TURN_BLOCK_HEIGHT}
          rx={2}
          fill="var(--status-critical)"
          fillOpacity={0.85}
        />
      )}
      <text
        x={width / 2}
        y={TURN_BLOCK_HEIGHT / 2 + 5}
        textAnchor="middle"
        fontSize={10}
        fill={color}
        fontFamily="var(--font-mono)"
      >
        {turn.turnIndex}
      </text>
    </g>
  );
}
export interface WorkflowTimelineProps {
  turns: TurnLevelResult[];
  handoffs?: HandoffEvaluation[];
  agentNames: string[];
  selectedAgents?: ReadonlySet<string>;
}
export function WorkflowTimeline({ turns, handoffs = [], agentNames, selectedAgents }: WorkflowTimelineProps) {
  if (turns.length === 0) {
    return <EmptyState message="No turns to display." />;
  }
  const visibleTurns = turns.length > MAX_VISIBLE_TURNS ? turns.slice(0, MAX_VISIBLE_TURNS) : turns;
  const truncated = turns.length > MAX_VISIBLE_TURNS;
  const visibleAgentNames = selectedAgents != null
    ? agentNames.filter(n => selectedAgents.has(n))
    : agentNames;
  const lanes = buildLanes(visibleTurns, visibleAgentNames);
  const totalTurns = visibleTurns.length;
  const visibleHandoffs = selectedAgents != null
    ? handoffs.filter(h => selectedAgents.has(h.sourceAgent) && selectedAgents.has(h.targetAgent))
    : handoffs;
  const agentLaneIndex = new Map<string, number>();
  const agentColorMap = new Map<string, string>();
  for (let i = 0; i < visibleAgentNames.length; i++) {
    const name = visibleAgentNames[i];
    if (name === undefined) continue;
    agentLaneIndex.set(name, i);
    agentColorMap.set(name, agentColor(name, agentNames));
  }
  const availableWidth = totalTurns * TURN_BLOCK_STRIDE;
  const svgWidth = LABEL_WIDTH + availableWidth + TURN_BLOCK_GAP;
  const svgHeight = HEADER_HEIGHT + lanes.length * LANE_HEIGHT;
  const turnX = (turnIndex: number): number =>
    LABEL_WIDTH + turnIndex * TURN_BLOCK_STRIDE + TURN_BLOCK_GAP;
  const laneY = (laneIndex: number): number =>
    HEADER_HEIGHT + laneIndex * LANE_HEIGHT + LANE_CENTER_OFFSET;
  return (
    <div
      className="overflow-x-auto"
      role="img"
      aria-label={`Workflow timeline: ${visibleAgentNames.length} agents, ${totalTurns} turns`}
    >
      <svg
        width={svgWidth}
        height={svgHeight}
        className="d-block timeline-svg"
        style={{ '--timeline-min-width': `${svgWidth}px` } as React.CSSProperties}
      >
        <g>
          {turns.map(t => (
            <text
              key={t.turnIndex}
              x={turnX(t.turnIndex) + TURN_BLOCK_MIN_WIDTH / 2}
              y={HEADER_HEIGHT - 8}
              textAnchor="middle"
              fontSize={9}
              fill="var(--text-muted)"
              fontFamily="var(--font-mono)"
            >
              {t.turnIndex}
            </text>
          ))}
        </g>
        {lanes.map(({ agentName, turns: laneTurns, laneIndex }) => {
          const color = agentColorMap.get(agentName) ?? agentColor(agentName, agentNames);
          const laneTop = HEADER_HEIGHT + laneIndex * LANE_HEIGHT;
          return (
            <g key={agentName}>
              <rect
                x={0}
                y={laneTop}
                width={svgWidth}
                height={LANE_HEIGHT}
                fill={laneIndex % 2 === 0 ? 'var(--bg-elevated)' : 'var(--bg-card)'}
                fillOpacity={0.5}
              />
              <line
                x1={0}
                y1={laneTop}
                x2={svgWidth}
                y2={laneTop}
                stroke="var(--border-subtle)"
                strokeWidth={1}
              />
              <text
                x={LABEL_WIDTH - 8}
                y={laneTop + LANE_CENTER_OFFSET + 4}
                textAnchor="end"
                fontSize={11}
                fontWeight={600}
                fill={color}
                fontFamily="var(--font-mono)"
              >
                {agentName.length > 12 ? `${agentName.slice(0, 10)}\u2026` : agentName}
              </text>
              {laneTurns.map(turn => (
                <TurnBlock
                  key={turn.turnIndex}
                  turn={turn}
                  color={color}
                  width={TURN_BLOCK_MIN_WIDTH}
                  x={turnX(turn.turnIndex)}
                  y={laneTop + LANE_PADDING_TOP}
                />
              ))}
            </g>
          );
        })}
        <line
          x1={0}
          y1={svgHeight}
          x2={svgWidth}
          y2={svgHeight}
          stroke="var(--border-subtle)"
          strokeWidth={1}
        />
        {visibleHandoffs.map((h) => {
          const turnIndex = findHandoffTurnIndex(h, turns);
          if (turnIndex == null) return null;
          const sourceLaneIdx = agentLaneIndex.get(h.sourceAgent) ?? -1;
          const targetLaneIdx = agentLaneIndex.get(h.targetAgent) ?? -1;
          if (sourceLaneIdx < 0 || targetLaneIdx < 0) return null;
          const x = turnX(turnIndex) + TURN_BLOCK_MIN_WIDTH / 2;
          const y1 = laneY(sourceLaneIdx);
          const y2 = laneY(targetLaneIdx);
          const midY = (y1 + y2) / 2;
          const handoffColor = h.correctTarget
            ? 'var(--status-healthy)'
            : 'var(--status-warning)';
          return (
            <g
              key={`handoff-${h.sourceAgent}-${h.targetAgent}-${turnIndex}`}
              role="img"
              aria-label={`Handoff from ${h.sourceAgent} to ${h.targetAgent}, score ${h.score.toFixed(SCORE_CHIP_PRECISION)}`}
            >
              <line
                x1={x}
                y1={y1}
                x2={x}
                y2={y2}
                stroke={handoffColor}
                strokeWidth={2}
                strokeDasharray="4 2"
                opacity={0.7}
              />
              <circle
                cx={x}
                cy={midY}
                r={HANDOFF_MARKER_RADIUS}
                fill="var(--bg-card)"
                stroke={handoffColor}
                strokeWidth={1.5}
              />
              <text
                x={x}
                y={midY + 4}
                textAnchor="middle"
                fontSize={8}
                fill={handoffColor}
                fontFamily="var(--font-mono)"
                fontWeight={600}
              >
                {h.score.toFixed(1)}
              </text>
            </g>
          );
        })}
      </svg>
      <div className="flex-wrap gap-4 mt-2 workflow-legend">
        <span className="text-2xs text-muted">Turn relevance bar at top of each block</span>
        {visibleHandoffs.length > 0 && (
          <span className="text-2xs text-muted">Dashed lines = handoffs with score</span>
        )}
        {truncated && (
          <span className="text-2xs text-warning">
            Showing first {MAX_VISIBLE_TURNS} of {turns.length} turns
          </span>
        )}
      </div>
    </div>
  );
}import { createContext, useContext, useCallback, useEffect, useMemo, useRef, useState, type ReactNode } from 'react';
type ShortcutKey = string;
type ComboKey = `${string} ${string}`;
interface Shortcut {
  key: ShortcutKey;
  description: string;
  scope: string;
  action: () => void;
}
function isComboKey(key: string): key is ComboKey {
  return key.includes(' ');
}
function comboPrefix(key: ComboKey): string {
  return key.split(' ')[0] ?? '';
}
interface KeyboardNavContextValue {
  shortcuts: Shortcut[];
  register: (key: ShortcutKey, description: string, scope: string, action: () => void) => () => void;
  overlayOpen: boolean;
  toggleOverlay: () => void;
}
const KeyboardNavContext = createContext<KeyboardNavContextValue | null>(null);
export function useShortcut(key: ShortcutKey, description: string, scope: string, action: () => void) {
  const ctx = useContext(KeyboardNavContext);
  if (!ctx) throw new Error('useShortcut must be used within KeyboardNavProvider');
  const { register } = ctx;
  const actionRef = useRef(action);
  useEffect(() => { actionRef.current = action; });
  const stableAction = useCallback(() => actionRef.current(), []);
  useEffect(() => register(key, description, scope, stableAction), [register, key, description, scope, stableAction]);
}
export function useKeyboardNav() {
  const ctx = useContext(KeyboardNavContext);
  if (!ctx) throw new Error('useKeyboardNav must be used within KeyboardNavProvider');
  return ctx;
}
const IGNORED_TAGS = new Set(['INPUT', 'TEXTAREA', 'SELECT']);
export function KeyboardNavProvider({ children }: { children: ReactNode }) {
  const shortcutsRef = useRef<Shortcut[]>([]);
  const [shortcuts, setShortcuts] = useState<Shortcut[]>([]);
  const [overlayOpen, setOverlayOpen] = useState(false);
  const overlayOpenRef = useRef(false);
  const pendingRef = useRef<string | null>(null);
  const pendingTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const register = useCallback((key: ShortcutKey, description: string, scope: string, action: () => void) => {
    const existing = shortcutsRef.current;
    const duplicate = existing.find(s => s.key === key);
    if (duplicate) throw new Error(`Shortcut conflict: "${key}" is already registered (${duplicate.description})`);
    if (isComboKey(key)) {
      const prefix = comboPrefix(key);
      const conflict = existing.find(s => s.key === prefix);
      if (conflict) throw new Error(`Shortcut conflict: combo "${key}" clashes with single-key "${prefix}" (${conflict.description})`);
    } else {
      const conflict = existing.find(s => isComboKey(s.key) && comboPrefix(s.key) === key);
      if (conflict) throw new Error(`Shortcut conflict: single-key "${key}" clashes with combo "${conflict.key}" (${conflict.description})`);
    }
    const shortcut: Shortcut = { key, description, scope, action };
    const next = [...existing, shortcut];
    shortcutsRef.current = next;
    setShortcuts(next);
    return () => {
      const filtered = shortcutsRef.current.filter(s => s !== shortcut);
      shortcutsRef.current = filtered;
      setShortcuts(filtered);
    };
  }, []);
  const toggleOverlay = useCallback(() => {
    setOverlayOpen(o => {
      overlayOpenRef.current = !o;
      return !o;
    });
  }, []);
  useEffect(() => {
    function handleKeydown(e: KeyboardEvent) {
      if (IGNORED_TAGS.has((e.target as HTMLElement | null)?.tagName ?? '')) return;
      if (e.ctrlKey || e.metaKey || e.altKey) return;
      const key = e.key;
      if (key === '?') {
        e.preventDefault();
        setOverlayOpen(o => {
          overlayOpenRef.current = !o;
          return !o;
        });
        return;
      }
      if (key === 'Escape' && overlayOpenRef.current) {
        e.preventDefault();
        overlayOpenRef.current = false;
        setOverlayOpen(false);
        return;
      }
      if (pendingRef.current) {
        const combo = `${pendingRef.current} ${key}`;
        pendingRef.current = null;
        if (pendingTimerRef.current) {
          clearTimeout(pendingTimerRef.current);
          pendingTimerRef.current = null;
        }
        const match = shortcutsRef.current.find(s => s.key === combo);
        if (match) {
          e.preventDefault();
          match.action();
          return;
        }
      }
      const single = shortcutsRef.current.find(s => s.key === key);
      if (single) {
        e.preventDefault();
        single.action();
        return;
      }
      const hasCombo = shortcutsRef.current.some(s => s.key.startsWith(`${key} `));
      if (hasCombo) {
        pendingRef.current = key;
        pendingTimerRef.current = setTimeout(() => { pendingRef.current = null; }, 500);
      }
    }
    document.addEventListener('keydown', handleKeydown);
    return () => {
      document.removeEventListener('keydown', handleKeydown);
      if (pendingTimerRef.current) clearTimeout(pendingTimerRef.current);
    };
  }, []);
  const value = useMemo<KeyboardNavContextValue>(
    () => ({ shortcuts, register, overlayOpen, toggleOverlay }),
    [shortcuts, register, overlayOpen, toggleOverlay],
  );
  return (
    <KeyboardNavContext.Provider value={value}>
      {children}
    </KeyboardNavContext.Provider>
  );
}import { createContext, useContext, useState, useCallback, useMemo, type ReactNode } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { useAuth } from './AuthContext.js';
import { API_BASE } from '../lib/constants.js';
import { apiFetch, getStoredOrgId, setStoredOrgId } from '../lib/api-client.js';
import type { OrgMembershipSummary } from '../types/auth.js';
interface OrgContextValue {
  activeOrgId: string | null;
  memberships: OrgMembershipSummary[];
  isStaff: boolean;
  switchOrg: (orgId: string) => Promise<boolean>;
}
const OrgContext = createContext<OrgContextValue | null>(null);
export function OrgProvider({ children }: { children: ReactNode }) {
  const { session, getAccessToken } = useAuth();
  const queryClient = useQueryClient();
  const [chosenOrgId, setChosenOrgId] = useState<string | null>(() => getStoredOrgId());
  const memberships = useMemo(() => session?.memberships ?? [], [session?.memberships]);
  const isStaff = session?.isStaff ?? false;
  const activeOrgId = useMemo(() => {
    if (chosenOrgId && (isStaff || memberships.some(m => m.orgId === chosenOrgId))) {
      return chosenOrgId;
    }
    return session?.activeOrgId ?? null;
  }, [chosenOrgId, isStaff, memberships, session?.activeOrgId]);
  const switchOrg = useCallback(async (orgId: string): Promise<boolean> => {
    try {
      const token = await getAccessToken();
      const res = await apiFetch(`${API_BASE}/api/org/switch`, token, orgId, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ orgId }),
      });
      if (!res.ok) return false;
      setStoredOrgId(orgId);
      setChosenOrgId(orgId);
      await queryClient.invalidateQueries();
      return true;
    } catch {
      return false;
    }
  }, [getAccessToken, queryClient]);
  const value = useMemo(
    () => ({ activeOrgId, memberships, isStaff, switchOrg }),
    [activeOrgId, memberships, isStaff, switchOrg],
  );
  return <OrgContext.Provider value={value}>{children}</OrgContext.Provider>;
}
export function useOrg(): OrgContextValue {
  const ctx = useContext(OrgContext);
  if (!ctx) throw new Error('useOrg must be used within an OrgProvider');
  return ctx;
}
export function useOrgOptional(): OrgContextValue | null {
  return useContext(OrgContext);
