      headers: { ...serviceHeaders, 'Prefer': 'return=representation' },
      body: JSON.stringify({ name: E2E_ROLE_NAME, permissions: E2E_PERMISSIONS }),
      signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
    });
    if (!createRes.ok) {
