async function fetchAppSession(jwt: string, signal?: AbortSignal): Promise<AppSession | null> {
  try {
    const res = await fetch(`${API_BASE}/api/me`, {
      method: 'GET',
      headers: { 'Authorization': `Bearer ${jwt}` },
      signal,
    });
    if (!res.ok) return null;
    const data: unknown = await res.json();
    const meResult = MeResponseSchema.safeParse(data);
    if (!meResult.success) return null;
    const me = meResult.data;
    return {
      email: me.email,
      roles: me.roles,
      permissions: me.permissions,
      allowedViews: me.allowedViews,
      ...(me.activeOrg !== undefined && { activeOrgId: me.activeOrg }),
      ...(me.memberships !== undefined && { memberships: me.memberships }),
      ...(me.role !== undefined && { role: me.role }),
      ...(me.isStaff !== undefined && { isStaff: me.isStaff }),
    };
  } catch {
    return null;
  }
}
export function AuthProvider({ children }: { children: ReactNode }) {
  const { isLoading: auth0Loading, isAuthenticated, getAccessTokenSilently, logout } = useAuth0();
  const [session, setSession] = useState<AppSession | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const getAccessToken = useCallback(
    () => getAccessTokenSilently({ authorizationParams: { audience: AUTH0_AUDIENCE } }),
    [getAccessTokenSilently],
  );
  useEffect(() => {
    if (auth0Loading) return;
    const controller = new AbortController();
    let cancelled = false;
    if (!isAuthenticated) {
      void Promise.resolve().then(() => {
        if (!cancelled) {
          setSession(null);
          setIsLoading(false);
        }
      });
      return () => {
        cancelled = true;
      };
    }
    getAccessToken()
      .then((jwt) => (cancelled ? null : fetchAppSession(jwt, controller.signal)))
      .then((appSession) => {
        if (!cancelled) {
          setSession(appSession);
          setIsLoading(false);
        }
      })
      .catch(() => {
        if (!cancelled) {
          setSession(null);
          setIsLoading(false);
        }
      });
    return () => {
      cancelled = true;
      controller.abort();
    };
  }, [auth0Loading, isAuthenticated, getAccessToken]);
  const handleSignOut = useCallback(async () => {
    if (session) {
      const jwt = await getAccessToken().catch(() => null);
      if (jwt) void fetch(`${API_BASE}/api/logout`, { method: 'POST', headers: { 'Authorization': `Bearer ${jwt}` } }).catch(() => undefined);
    }
    await logout({ logoutParams: { returnTo: window.location.origin } });
  }, [session, logout, getAccessToken]);
  return (
    <AuthContext.Provider value={{ session, isLoading, signOut: handleSignOut, getAccessToken }}>
      {children}
    </AuthContext.Provider>
  );
}
export function useAuth(): AuthContextValue {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error('useAuth must be used within an AuthProvider');
  return ctx;
}import { useState, useCallback, useEffect, lazy, Suspense, type ReactNode } from 'react';
