  --status-healthy-muted: color-mix(in srgb, var(--status-healthy) var(--chip-tint), transparent);
  --radius-xs: 2px;
  --radius-bar: 3px;
  --radius-sm: 4px;
  --radius: 6px;
  --radius-lg: 8px;
  --radius-pill: 12px;
  --radius-full: 50%;
  --border-width-thin: 1px;
  --border-width-thick: 2px;
  --border-width-rail: 3px;
  --font-size-2xs: 9px;
  --font-size-xs: 12px;
  --font-size-base: 14px;
  --font-size-md: 16px;
  --font-size-lg: 18px;
  --font-size-xl: 20px;
  --font-size-stat: 22px;
  --font-size-2xl: 24px;
  --font-size-3xl: 36px;
  --bold: 600;
  --light-bold: 500;
  --label-letter-spacing: 0.5px;
  --stat-label-letter-spacing: 0.1em;
  --letter-spacing-id: 0.02em;
  --label-letter-spacing-wide: 0.12em;
  --transition-fast: 0.15s ease;
  --transition-medium: 0.2s ease;
  --transition-bar: width 0.3s ease;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.3);
  --shadow-glow-healthy: 0 0 12px var(--healthy-alpha-15);
  --shadow-glow-warning: 0 0 12px var(--warning-alpha-15);
  --shadow-glow-critical: 0 0 12px var(--critical-alpha-20);
  --wf-node-bg: #f9fafb;
  --wf-node-border: #d1d5db;
  --wf-score-high-bg: #dcfce7;
  --wf-score-high-border: #16a34a;
  --wf-score-high-text: #15803d;
  --wf-score-mid-bg: #fef9c3;
  --wf-score-mid-border: #ca8a04;
  --wf-score-mid-text: #a16207;
  --wf-score-low-bg: #fee2e2;
  --wf-score-low-border: #dc2626;
  --wf-score-low-text: #b91c1c;
  --wf-cluster-bg: #eef2ff;
  --wf-cluster-accent: #6366f1;
  --wf-cluster-accent-strong: #4338ca;
  --wf-fallback-empty: #9ca3af;
}
.overflow-x-auto { overflow-x: auto; }
.select-none { user-select: none; }
.cursor-pointer { cursor: pointer; }
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}
.summary-count .label,
.sla-table th,
.cot-summary,
.agreement-grid .ag-header,
.stat-label,
.field-label,
.uppercase {
  text-transform: uppercase;
  letter-spacing: var(--label-letter-spacing);
}
.back-link,
.tooltip-link,
.alert-metric-link {
  color: var(--accent);
  text-decoration: none;
}
.back-link:hover,
.tooltip-link:hover,
.alert-metric-link:hover {
  text-decoration: underline;
}
.summary-count { text-align: center; }
.card:hover { border-color: var(--border); }
.trend.stable { color: var(--text-secondary); }
.card.glow-critical { box-shadow: var(--shadow-glow-critical); }
.card.glow-warning { box-shadow: var(--shadow-glow-warning); }
body {
  font-family: var(--font-body);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  font-size: var(--font-size-base);
  -webkit-font-smoothing: antialiased;
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}
.dashboard-container {
  max-width: var(--layout-max-width);
  margin: 0 auto;
  padding: var(--space-6);
}
.metric-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: var(--space-4);
}
.card {
  background: var(--bg-card);
  border: var(--border-width-thin) solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: var(--space-5);
  box-shadow: var(--shadow-sm);
}
.card-link {
  text-decoration: none;
  color: inherit;
  display: block;
}
[data-status="healthy"]  { --s-bg: var(--bg-status-healthy);  --s-border: var(--border-status-healthy);  --s-fg: var(--status-healthy); }
[data-status="warning"]  { --s-bg: var(--bg-status-warning);  --s-border: var(--border-status-warning);  --s-fg: var(--status-warning); }
[data-status="critical"] { --s-bg: var(--bg-status-critical); --s-border: var(--border-status-critical); --s-fg: var(--status-critical); }
[data-status="no_data"]  { --s-bg: var(--bg-elevated);         --s-border: var(--border);                  --s-fg: var(--status-no-data); }
[data-status="info"]     { --s-bg: var(--bg-elevated);         --s-border: var(--border);                  --s-fg: var(--text-secondary); }
[data-band="excellent"] { --band-fg: var(--score-excellent); }
[data-band="good"]      { --band-fg: var(--score-good); }
[data-band="adequate"]  { --band-fg: var(--score-adequate); }
[data-band="poor"]      { --band-fg: var(--score-poor); }
[data-band="failing"]   { --band-fg: var(--score-failing); }
.health-banner {
  padding: var(--space-4) var(--space-5);
  border-radius: var(--radius);
  margin-bottom: var(--space-6);
  justify-content: space-between;
}
.health-banner[data-status] { background: var(--s-bg); border: var(--border-width-thin) solid var(--s-border); }
.summary-count .value {
  font-size: var(--font-size-2xl);
  font-weight: var(--bold);
  font-family: var(--font-mono);
}
.status-badge {
  gap: var(--space-1-5);
  font-weight: var(--light-bold);
  padding: var(--space-px) var(--space-2);
  border-radius: var(--radius-pill);
}
.status-badge[data-status] { color: var(--s-fg); background: var(--s-bg); }
.trend {
  gap: var(--space-1);
  font-size: var(--font-size-xs);
  font-family: var(--font-mono);
}
.trend.improving { color: var(--status-healthy); }
.trend.degrading { color: var(--status-critical); }
.chart-dynamics { color: var(--chart-text); }
.chart-line-indicator { color: var(--chart-line); }
.chart-breach-time { color: var(--status-warning); }
.chart-breach-time[data-status="critical"] { color: var(--status-critical); }
.metric-card-header {
  justify-content: space-between;
  margin-bottom: var(--space-3);
}
.metric-card-header h3 {
  font-size: var(--font-size-base);
  font-weight: var(--light-bold);
}
.metric-values {
  font-family: var(--font-mono);
  font-size: var(--font-size-xs);
}
.metric-values .primary {
  font-size: var(--font-size-2xl);
  font-weight: var(--bold);
  line-height: 1.2;
}
.metric-values .secondary {
  color: var(--text-secondary);
  margin-top: var(--space-1);
}
.metric-footer,
.pipeline-stats,
.agreement-summary {
  margin-top: var(--space-3);
  padding-top: var(--space-3);
  border-top: var(--border-width-thin) solid var(--border-subtle);
  font-size: var(--font-size-xs);
  color: var(--text-secondary);
}
.metric-footer {
  justify-content: space-between;
  border-top-color: var(--border);
}
.alert-list {
  list-style: none;
}
.alert-item {
  padding: var(--space-3) var(--space-4);
  border-left: var(--border-width-rail) solid;
  background: var(--bg-card);
  margin-bottom: var(--space-2);
  border-radius: 0 var(--radius) var(--radius) 0;
}
.alert-item[data-status] { border-left-color: var(--s-fg); }
.alert-item .alert-meta,
.alert-item .remediation {
  margin-top: var(--space-1);
}
.alert-item .remediation { color: var(--accent); }
.data-table { width: 100%; border-collapse: collapse; }
.data-table th,
.data-table td { border-bottom: var(--border-width-thin) solid var(--border); }
.data-table th {
  font-size: var(--font-size-xs);
  text-align: left;
  color: var(--text-secondary);
  font-weight: var(--light-bold);
}
.sla-table { font-size: var(--font-size-base); }
.sla-table th,
.sla-table td { padding: var(--space-2) var(--space-3); }
.sla-table .col-agent { width: 30%; }
.sla-gap-cell { color: var(--status-healthy); }
.sla-gap-cell[data-noncompliant] { color: var(--status-critical); }
.t2-stage-notice {
  padding: var(--space-2-5) var(--space-3-5);
  border-radius: var(--radius);
  border: var(--border-width-thin) dashed var(--border);
  background: var(--bg-surface);
}
.t2-stage-badge {
  border-radius: var(--radius-full);
  background: var(--accent);
  color: var(--text-on-accent);
  width: 24px;
  height: 24px;
}
.turn-card {
  border-radius: var(--radius-lg);
  background: var(--bg-elevated);
  min-width: 120px;
  border: var(--border-width-thick) solid var(--turn-color, var(--border));
}
.turn-card-agent { color: var(--turn-color, var(--text-secondary)); }
.histogram {
  display: flex;
  align-items: flex-end;
  gap: var(--space-px);
  height: 120px;
  padding: var(--space-2) 0;
}
.histogram-bar {
  flex: 1;
  height: var(--histogram-bar-height);
  background: var(--accent);
  border-radius: var(--radius-xs) var(--radius-xs) 0 0;
  min-height: var(--space-px);
  position: relative;
}
.histogram-bar:hover {
  opacity: 0.8;
}
.histogram-bar .tooltip,
.score-badge-tooltip {
  display: none;
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
  font-size: var(--font-size-xs);
}
.histogram-bar .tooltip {
  bottom: 100%;
  padding: var(--space-1) var(--space-2);
  border-radius: var(--radius-sm);
  white-space: nowrap;
  z-index: 10;
}
.histogram-bar:hover .tooltip {
  display: block;
}
.histogram-labels {
  display: flex;
  justify-content: space-between;
  font-size: var(--font-size-xs);
  color: var(--text-muted);
  font-family: var(--font-mono);
}
.eval-table {
  font-size: var(--font-size-xs);
}
.eval-table th,
.eval-table td {
  padding: var(--space-1-5) var(--space-2-5);
}
.eval-table td {
  font-family: var(--font-mono);
}
.eval-table .explanation {
  font-family: inherit;
  color: var(--text-secondary);
  max-width: 300px;
}
.eval-table tbody tr:hover,
.eval-table .eval-row-expanded {
  background: var(--bg-elevated);
}
.eval-table .eval-expanded-panel td {
  padding: 0 var(--space-2-5) var(--space-2-5);
}
.eval-expanded-content {
  background: var(--bg-elevated);
  border-radius: var(--radius);
  padding: var(--space-4);
  animation: fade-in var(--transition-fast);
}
.pad-panel-section { padding: var(--space-2-5) 0 var(--space-2); }
.pad-panel-sparse  { padding: var(--space-2-5) 0 var(--space-1); }
.tab-btn,
.period-btn {
  background: none;
  border: none;
  color: var(--text-secondary);
  cursor: pointer;
}
.tab-nav {
  display: flex;
  gap: var(--space-1);
  margin-bottom: var(--space-6);
  border-bottom: var(--border-width-thin) solid var(--border);
}
.tab-btn {
  padding: var(--space-2) var(--space-4);
  font-size: var(--font-size-base);
  border-bottom: var(--border-width-thick) solid transparent;
  margin-bottom: -1px;
  transition: color var(--transition-fast), border-color var(--transition-fast);
}
.tab-btn:hover {
  color: var(--text-primary);
}
.tab-btn[aria-selected="true"] {
  color: var(--text-primary);
  border-bottom-color: var(--accent);
}
.period-selector {
  display: inline-flex;
  gap: var(--space-1);
  background: var(--bg-elevated);
  border-radius: var(--radius);
  padding: var(--space-px);
}
.period-btn {
  padding: var(--space-1) var(--space-3);
  border-radius: var(--radius);
  font-size: var(--font-size-xs);
  font-family: var(--font-body);
}
.period-btn.active {
  background: var(--bg-card);
  color: var(--text-primary);
}
.header {
  justify-content: space-between;
  margin-bottom: var(--space-6);
}
.header-actions {
  display: inline-flex;
  align-items: center;
  gap: var(--space-3);
}
.logout-btn {
  color: var(--text-secondary);
}
.logout-btn:hover {
  color: var(--text-primary);
}
.logout-btn:disabled {
  opacity: 0.6;
  cursor: default;
}
.header h1 {
  font-size: var(--font-size-xl);
  font-weight: var(--bold);
}
.page-skeleton { height: var(--skeleton-height, 300px); }
.skeleton {
  background: linear-gradient(90deg, var(--bg-card) 25%, var(--bg-elevated) 50%, var(--bg-card) 75%);
  background-size: 200% 100%;
  animation: skeleton-pulse 1.5s ease-in-out infinite;
  border-radius: var(--radius);
}
@keyframes skeleton-pulse {
  0% { background-position: 200% 0; }
  100% { background-position: -200% 0; }
}
.empty-state {
  text-align: center;
  padding: var(--space-16) var(--space-6);
  color: var(--text-secondary);
}
.empty-state h2 {
  color: var(--text-primary);
  margin-bottom: var(--space-2);
}
.empty-state code {
  background: var(--bg-elevated);
  padding: var(--space-px) var(--space-1-5);
  border-radius: var(--radius-sm);
  font-family: var(--font-mono);
  font-size: var(--font-size-xs);
}
.back-link {
  font-size: var(--font-size-xs);
  gap: var(--space-1);
  margin-bottom: var(--space-4);
}
.error-state {
  background: var(--bg-status-critical);
  border: var(--border-width-thin) solid var(--border-status-critical);
  border-radius: var(--radius);
  padding: var(--space-6);
  text-align: center;
}
.error-state h2 {
  color: var(--status-critical);
  margin-bottom: var(--space-2);
}
.error-state .error-actions {
  display: flex;
  gap: var(--space-2);
  margin-top: var(--space-3);
  justify-content: center;
}
.error-state .error-actions button,
.error-state .error-actions a {
  padding: var(--space-1-5) var(--space-4);
  cursor: pointer;
}
.section-heading {
  font-size: var(--font-size-md);
  font-weight: var(--bold);
  margin-bottom: var(--space-4);
  margin-top: var(--space-8);
}
.ls-id { letter-spacing: var(--letter-spacing-id); }
.issue-callout {
  border-left: var(--border-width-rail) solid var(--s-fg);
  background: var(--s-bg);
  border-radius: 0 var(--radius) var(--radius) 0;
  padding: var(--space-2-5) var(--space-3-5);
}
.issue-callout .callout-title { color: var(--s-fg); }
.page-content { max-width: var(--page-content-max-width); }
.centered-callout {
  max-width: var(--callout-max-width, 480px);
  margin: 0 auto;
}
.card-spacious {
  padding: var(--space-8) var(--space-6);
}
.stat-label-section {
  letter-spacing: var(--label-letter-spacing-wide);
  margin: var(--space-3-5) 0 var(--space-2);
}
.commit-summary {
  padding: var(--space-2) var(--space-1);
}
.commit-detail {
  padding-left: var(--space-5);
  padding-bottom: var(--space-2-5);
}
.commit-body {
  font-family: var(--font-body);
}
.agent-stat-card {
  background: var(--bg-elevated);
  border: var(--border-width-thin) solid var(--border-subtle);
  border-radius: var(--radius);
  padding: var(--space-2-5) var(--space-3-5);
}
.agent-stat-card[data-has-error='true'] {
  border-color: var(--status-warning);
}
.session-detail-header {
  background: var(--bg-card);
  border: var(--border-width-thin) solid var(--border-subtle);
  border-bottom: none;
  padding: var(--space-5) var(--space-6) var(--space-4);
  margin-bottom: 0;
}
.session-vitals-strip {
  background: var(--bg-elevated);
  border: var(--border-width-thin) solid var(--border-subtle);
  border-bottom: var(--border-width-thin) solid var(--border);
  padding: var(--space-3-5) var(--space-6);
  row-gap: var(--space-3);
  margin-bottom: var(--space-0-5);
}
.stat-item {
  flex: 1 1 100px;
  min-width: 80px;
  text-align: center;
}
.stat-value {
  font-size: var(--font-size-stat);
  line-height: 1.1;
}
.stat-label {
  font-size: var(--font-size-xs);
  font-family: var(--font-mono);
  color: var(--text-muted);
  letter-spacing: var(--stat-label-letter-spacing);
  margin-top: var(--space-px);
}
.freq-bar-row {
  display: grid;
  grid-template-columns: 160px 1fr 36px;
  align-items: center;
  gap: var(--space-2-5);
  margin-bottom: var(--space-1-5);
}
.vitals-divider {
  width: 1px;
  background: var(--border-subtle);
  margin: 0 var(--space-2);
  align-self: stretch;
}
.freq-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(340px, 1fr));
  gap: 0 var(--space-8);
}
.view-section {
  margin-bottom: var(--space-8);
}
.refetch-indicator {
  position: fixed;
  top: var(--space-4);
  right: var(--space-4);
  padding: var(--space-2) var(--space-4);
  border-radius: var(--radius);
  font-size: var(--font-size-xs);
  color: var(--text-secondary);
  z-index: 1000;
  animation: fade-in var(--transition-fast);
}
@keyframes fade-in {
  from { opacity: 0; transform: translateY(-8px); }
  to { opacity: 1; transform: translateY(0); }
}
@keyframes toxicPulse {
  0%, 100% { box-shadow: 0 0 0 0 var(--critical-alpha-40); }
  50% { box-shadow: 0 0 6px 2px var(--critical-alpha-60); }
}
.score-badge-wrapper {
  position: relative;
  cursor: default;
}
.score-no-data { color: var(--status-no-data); }
.score-badge-tooltip {
  bottom: calc(100% + var(--space-2));
  border-radius: var(--radius);
  padding: var(--space-2-5) var(--space-3);
  min-width: 200px;
  max-width: 300px;
  z-index: 20;
  white-space: normal;
  animation: fade-in var(--transition-fast);
}
.score-badge-wrapper:hover .score-badge-tooltip,
.score-badge-wrapper:focus-within .score-badge-tooltip {
  display: block;
}
.tooltip-row {
  display: flex;
  justify-content: space-between;
  gap: var(--space-3);
  padding: var(--space-px) 0;
  color: var(--text-primary);
}
.tooltip-row--col { flex-direction: column; }
.tooltip-link {
  display: block;
  margin-top: var(--space-2);
  padding-top: var(--space-1-5);
  border-top: var(--border-width-thin) solid var(--border);
}
.cot-panel {
  margin-top: var(--space-1);
}
.cot-summary {
  color: var(--text-secondary);
  cursor: pointer;
  padding: var(--space-1) 0;
  list-style: none;
}
.cot-summary::-webkit-details-marker {
  display: none;
}
.cot-summary::before {
  content: '\25B6';
  display: inline-block;
  margin-right: var(--space-1-5);
  font-size: var(--font-size-2xs);
  transition: transform var(--transition-fast);
}
details[open] > .cot-summary::before {
  transform: rotate(90deg);
}
.cot-content {
  font-size: var(--font-size-xs);
  color: var(--text-primary);
  line-height: 1.6;
  padding: var(--space-2) 0 var(--space-1);
}
.eval-detail-header {
  margin-bottom: var(--space-6);
}
.eval-detail-meta {
  gap: var(--space-4);
  margin-top: var(--space-2);
}
.eval-detail-card {
  margin-bottom: var(--space-4);
}
.eval-overlay-card {
  padding: var(--space-1) var(--space-2);
  border-radius: var(--radius);
}
.eval-summary-card {
  cursor: pointer;
  transition: border-color var(--transition-fast);
}
.eval-summary-card.card:hover {
  border-color: var(--accent);
}
.link-plain {
  text-decoration: none;
  color: inherit;
}
.span-row {
  padding-top: var(--space-2);
  padding-bottom: var(--space-2);
  padding-left: var(--span-row-indent, 0);
}
.span-status-icon { color: var(--text-primary); }
.span-status-icon[data-error] { color: var(--status-critical); }
.span-bar {
  height: var(--space-1);
  width: var(--span-bar-width);
  min-width: var(--span-bar-min-width, 0);
  background: var(--status-healthy);
  border-radius: var(--radius-xs);
  margin-top: var(--space-1);
}
.span-bar[data-error] { background: var(--status-critical); }
.quality-live-bar {
  flex-wrap: wrap;
  padding: var(--space-1-5) var(--space-3);
  border-radius: var(--radius);
}
.quality-chip {
  background: color-mix(in srgb, var(--chip-color) var(--chip-tint), transparent);
  color: var(--chip-color);
}
.quality-chip .dot-xs { background: var(--chip-color); }
.cqi-value {
  font-size: var(--font-size-3xl);
  line-height: 1.2;
  color: var(--cqi-color, var(--text-primary));
}
.cqi-segment { min-width: var(--space-0-5); flex: var(--cqi-segment-flex); background-color: var(--cqi-segment-bg); }
.cqi-segment-bar {
  height: var(--space-2);
  border-radius: var(--radius-sm);
  overflow: hidden;
}
.heatmap-grid { display: grid; aspect-ratio: var(--heatmap-aspect); grid-template-columns: var(--heatmap-grid-cols); grid-template-rows: var(--heatmap-grid-rows); }
.heatmap-row-header {
  justify-content: flex-end;
  padding-right: var(--space-2);
}
.heatmap-cell {
  border-radius: var(--radius-xs);
  min-height: 36px;
  border: none;
  background-color: var(--heatmap-cell-bg);
  color: var(--heatmap-cell-fg);
}
.heatmap-cell[data-toxic] {
  border: var(--border-width-thick) solid var(--score-failing);
  animation: toxicPulse 2s ease-in-out infinite;
}
.metric-card-compact {
  background: var(--bg-card);
  border: var(--border-width-thin) solid var(--border-subtle);
  border-radius: var(--radius);
  padding: var(--space-2) var(--space-2-5);
  min-width: 140px;
}
.agent-activity-table {
  min-width: 640px;
}
.agent-inv-bar {
  min-width: 48px;
}
.agent-inv-count { min-width: var(--space-8); }
.agent-dot { background: var(--agent-color, var(--border)); }
.agent-err-rate { color: var(--status-critical); }
.agent-err-rate[data-err-status="ok"] { color: var(--status-healthy); }
.agent-err-rate[data-err-status="warn"] { color: var(--status-warning); }
.score-band { color: var(--band-fg); }
.grid-two-col,
.agent-expanded-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
}
.score-label-width {
  min-width: var(--space-8);
}
.agent-expanded-grid {
  gap: var(--space-4);
  padding: var(--space-3) 0 var(--space-1);
}
.alert-compound {
  border-left-width: var(--space-1);
  background: var(--bg-elevated);
}
.alert-related {
  flex-wrap: wrap;
  gap: var(--space-2);
  margin-top: var(--space-2);
}
.alert-metric-link {
  font-family: var(--font-mono);
  padding: var(--space-px) var(--space-2);
  border-radius: var(--radius-pill);
  background: var(--accent-alpha-10);
}
.alert-metric-link:hover {
  background: var(--accent-alpha-20);
}
.remediation-list {
  margin-top: var(--space-2);
  padding-left: var(--space-5);
  color: var(--accent);
}
.remediation-list li {
  margin-bottom: var(--space-1);
}
.threshold-bar {
  position: relative;
  height: var(--space-1-5);
  background: var(--bg-card);
  border-radius: var(--radius-bar);
  margin-top: var(--space-2);
  overflow: visible;
}
.threshold-bar-fill,
.variance-bar-fill {
  height: 100%;
  transition: var(--transition-bar);
}
.threshold-bar-fill { width: var(--bar-fill-width); border-radius: var(--radius-bar); background: var(--status-healthy); }
.threshold-bar-fill[data-violating] { background: var(--status-critical); }
.variance-bar-fill  { border-radius: var(--radius-xs); }
.threshold-bar-marker {
  position: absolute;
  top: -3px;
  left: var(--bar-marker-left);
  width: 2px;
  height: 12px;
  background: var(--text-primary);
  border-radius: calc(var(--radius-xs) / 2);
  transform: translateX(-1px);
}
.pipeline-stat {
  gap: var(--space-1);
}
.pipeline-stat .stat-value {
  font-family: var(--font-mono);
  color: var(--text-primary);
  font-weight: var(--light-bold);
}
.funnel-bar {
  width: var(--funnel-width);
  background: var(--funnel-bg, var(--accent));
  border-radius: var(--radius-sm);
  align-items: center;
  justify-content: space-between;
  padding: 0 var(--space-2-5);
  transition: var(--transition-bar);
  min-width: 40px;
  height: 32px;
}
.funnel-dropoff {
  padding-left: var(--space-2-5);
  margin: var(--space-0-5) 0;
  color: var(--text-secondary);
}
.funnel-dropoff[data-warn] {
  color: var(--status-warning);
}
.metric-worst {
  font-size: var(--font-size-xs);
  color: var(--text-muted);
  margin-top: var(--space-2);
  line-height: 1.4;
}
.metric-worst .worst-score {
  color: var(--score-failing);
  font-family: var(--font-mono);
  font-weight: var(--light-bold);
}
.provenance-grid,
.agreement-grid,
.confidence-stats-grid {
  display: grid;
  gap: var(--space-1) var(--space-4);
}
.provenance-grid,
.agreement-grid {
  font-family: var(--font-mono);
  font-size: var(--font-size-xs);
}
.provenance-grid,
.confidence-stats-grid { grid-template-columns: auto 1fr; }
.agreement-grid { grid-template-columns: 1fr auto auto; }
.provenance-grid .prov-label {
  color: var(--text-secondary);
  font-family: var(--font-body);
  white-space: nowrap;
}
.provenance-grid .prov-value {
  color: var(--text-primary);
  word-break: break-all;
}
.provenance-actions {
  display: flex;
  gap: var(--space-2);
  margin-top: var(--space-3);
}
.provenance-actions button {
  background: var(--bg-surface);
  border: var(--border-width-thin) solid var(--border);
  color: var(--accent);
  padding: var(--space-1) var(--space-3);
  border-radius: var(--radius-sm);
  cursor: pointer;
  font-family: var(--font-body);
}
.provenance-actions button:hover {
  background: var(--bg-hover);
  border-color: var(--border-accent);
}
.confidence-header {
  gap: var(--space-2);
  margin-bottom: var(--space-3);
}
.confidence-level-indicator { color: var(--score-failing); }
.confidence-level-indicator[data-level="high"] { color: var(--score-excellent); }
.confidence-level-indicator[data-level="medium"] { color: var(--score-adequate); }
.agreement-value { color: var(--band-fg, var(--score-failing)); }
.confidence-method {
  font-family: var(--font-mono);
  font-size: var(--font-size-xs);
  color: var(--text-muted);
}
.agreement-grid .ag-header {
  color: var(--text-muted);
  font-size: var(--font-size-xs);
  font-family: var(--font-body);
  padding-bottom: var(--space-1);
  border-bottom: var(--border-width-thin) solid var(--border-subtle);
}
.agreement-summary .summary-value {
  font-family: var(--font-mono);
  color: var(--text-primary);
}
.variance-bar {
  gap: var(--space-2);
}
.bar-track,
.variance-bar-track,
.mini-bar {
  height: var(--bar-h, var(--space-1));
  background: var(--bar-track-color, var(--bg-surface));
  border-radius: var(--radius-xs);
}
.variance-bar-track,
.mini-bar { overflow: hidden; }
.variance-bar-track { flex: 1; }
.mini-bar-fill {
  height: 100%;
  width: var(--bar-fill-width);
  background: var(--bar-fill-color, var(--accent));
  opacity: var(--bar-fill-opacity, 1);
  border-radius: var(--radius-xs);
  transition: var(--transition-bar);
}
.card--empty {
  padding: var(--space-4);
  color: var(--text-muted);
}
.mono      { font-family: var(--font-mono); }
.mono-2xs  { font-family: var(--font-mono); font-size: var(--font-size-2xs); }
.mono-xs   { font-family: var(--font-mono); font-size: var(--font-size-xs); }
.mono-base { font-family: var(--font-mono); font-size: var(--font-size-base); }
.mono-md   { font-family: var(--font-mono); font-size: var(--font-size-md); }
.mono-lg   { font-family: var(--font-mono); font-size: var(--font-size-lg); }
.mono-xl   { font-family: var(--font-mono); font-size: var(--font-size-xl); }
.mono-2xl  { font-family: var(--font-mono); font-size: var(--font-size-2xl); }
.text-2xs  { font-size: var(--font-size-2xs); }
.text-xs   { font-size: var(--font-size-xs); }
.text-base { font-size: var(--font-size-base); }
.text-md   { font-size: var(--font-size-md); }
.text-lg   { font-size: var(--font-size-lg); }
.text-xl   { font-size: var(--font-size-xl); }
.text-2xl  { font-size: var(--font-size-2xl); }
.text-secondary    { color: var(--text-secondary); }
.text-muted        { color: var(--text-muted); }
.text-accent       { color: var(--accent); }
.text-accent-hover { color: var(--accent-hover); }
.text-on-accent    { color: var(--text-on-accent); }
.d-flex         { display: flex; }
.d-grid         { display: grid; }
.d-inline-block { display: inline-block; }
.d-block        { display: block; }
.timeline-svg   { min-width: var(--timeline-min-width); }
.flex-center    { display: flex; align-items: center; }
.align-start    { align-items: flex-start; }
.font-normal   { font-weight: 400; }
.font-semibold { font-weight: var(--bold); }
.chip { padding: var(--space-px) var(--space-1-5); border-radius: var(--radius-pill); }
.chip-colored {
  color: var(--chip-color);
  background-color: color-mix(in srgb, var(--chip-color) var(--chip-tint), transparent);
}
.gap-half { gap: var(--space-px); }
.gap-1    { gap: var(--space-1); }
.gap-1-5  { gap: var(--space-1-5); }
.gap-2    { gap: var(--space-2); }
.gap-2-5  { gap: var(--space-2-5); }
.gap-3    { gap: var(--space-3); }
.gap-4    { gap: var(--space-4); }
.gap-5    { gap: var(--space-5); }
.gap-6    { gap: var(--space-6); }
.gap-8    { gap: var(--space-8); }
.gap-16   { gap: var(--space-16); }
.w-full   { width: 100%; }
.min-w-120 { min-width: 120px; }
.m-0    { margin: 0; }
.ml-1   { margin-left: var(--space-1); }
.ml-2   { margin-left: var(--space-2); }
.ml-auto { margin-left: auto; }
.mr-1   { margin-right: var(--space-1); }
.mb-0   { margin-bottom: 0; }
.mb-1   { margin-bottom: var(--space-1); }
.mb-1-5 { margin-bottom: var(--space-1-5); }
.mb-2   { margin-bottom: var(--space-2); }
.mb-2-5 { margin-bottom: var(--space-2-5); }
.mb-3   { margin-bottom: var(--space-3); }
.mb-4   { margin-bottom: var(--space-4); }
.mb-5   { margin-bottom: var(--space-5); }
.mb-6   { margin-bottom: var(--space-6); }
.mt-0-5 { margin-top: var(--space-0-5); }
.mt-1   { margin-top: var(--space-1); }
.mt-2   { margin-top: var(--space-2); }
.mt-3   { margin-top: var(--space-3); }
.mt-4   { margin-top: var(--space-4); }
.my-2   { margin-top: var(--space-2); margin-bottom: var(--space-2); }
.p-4    { padding: var(--space-4); }
.p-4-5  { padding: var(--space-4) var(--space-5); }
.p-6    { padding: var(--space-6); }
.py-2   { padding-top: var(--space-2); padding-bottom: var(--space-2); }
.text-center { text-align: center; }
.text-right  { text-align: right; }
.text-left   { text-align: left; }
.flex-wrap          { display: flex; flex-wrap: wrap; }
.flex-col           { display: flex; flex-direction: column; }
.inline-flex-center { display: inline-flex; align-items: center; }
.shrink-0           { flex-shrink: 0; }
.flex-1             { flex: 1; }
.justify-between    { justify-content: space-between; }
.justify-center     { justify-content: center; }
.contents { display: contents; }
.opacity-30 { opacity: 0.3; }
.opacity-50 { opacity: 0.5; }
.list-none { list-style: none; }
.valign-middle { vertical-align: middle; }
.table-collapse { border-collapse: collapse; }
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
}
.font-medium { font-weight: var(--light-bold); }
.font-bold   { font-weight: 700; }
.italic      { font-style: italic; }
.nowrap      { white-space: nowrap; }
.truncate  { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.break-all { word-break: break-all; }
.leading-normal  { line-height: 1.5; }
.leading-relaxed { line-height: 1.6; }
.pt-2 { padding-top: var(--space-2); }
.pt-3 { padding-top: var(--space-3); }
.form-select { padding: var(--space-1) var(--space-2); border-radius: var(--radius-sm); border: var(--border-width-thin) solid var(--border); }
.btn-reset { background: none; border: none; padding: 0; }
.btn-xs { border: var(--border-width-thin) solid var(--border); padding: var(--space-1-5) var(--space-3); border-radius: var(--radius); }
.btn-sm { padding: var(--space-1-5) var(--space-4); }
.btn-expand { padding: var(--space-px) var(--space-1-5); }
.expand-chevron {
  display: inline-block;
  transition: transform var(--transition-fast);
  line-height: 1;
}
.expand-chevron--open {
  transform: rotate(90deg);
}
.text-healthy  { color: var(--status-healthy); }
.text-warning  { color: var(--status-warning); }
.text-critical { color: var(--status-critical); }
.text-primary  { color: var(--text-primary); }
.surface-elevated,
.surface-elevated-card { background: var(--bg-elevated); border: var(--border-width-thin) solid var(--border); }
.surface-elevated-card {
  padding: var(--space-2) var(--space-3);
  border-radius: var(--radius-lg);
}
.link-accent { color: var(--accent); text-decoration: none; }
.cell-pad      { padding: var(--space-1) var(--space-2-5); }
.cell-pad-wide { padding: var(--space-1) var(--space-3); }
.border-b        { border-bottom: var(--border-width-thin) solid var(--border); }
.border-b-subtle { border-bottom: var(--border-width-thin) solid var(--border-subtle); }
.border-t        { border-top: var(--border-width-thin) solid var(--border); }
.chip-badge {
  background: var(--bg-elevated);
  border: var(--border-width-thin) solid var(--border-subtle);
}
.chip-accent {
  background: var(--accent-alpha-10);
  color: var(--accent);
}
.chip-accent-muted {
  background: var(--accent-muted);
  color: var(--accent-hover);
}
.chip-healthy {
  background: var(--status-healthy-muted);
  color: var(--status-healthy);
}
.dot-sm,
.dot-xs {
  border-radius: var(--radius-full);
  display: inline-block;
  flex-shrink: 0;
}
.dot-sm { width: 8px; height: 8px; }
.dot-xs { width: 6px; height: 6px; }
.badge-warning {
  color: var(--status-warning);
  background: var(--bg-status-warning);
  padding: var(--space-px) var(--space-1-5);
  border-radius: var(--radius-pill);
}
.section-rail {
  background: var(--bg-card);
  border-left: var(--border-width-rail) solid var(--section-rail-color, var(--border-accent));
}
summary.section-rail {
  padding: var(--space-3) var(--space-5);
  transition: background var(--transition-fast);
}
.section-rail-body {
  padding: var(--space-4) var(--space-5) var(--space-5);
}
.section-rail-chevron {
  color: var(--section-rail-color, var(--border-accent));
  transition: transform var(--transition-medium);
}
.workflow-graph-container { height: var(--workflow-graph-height, 600px); }
.workflow-node {
  width: 220px;
  height: 120px;
  border: 2px solid var(--wf-node-border);
  border-radius: var(--radius-lg);
  background: var(--wf-node-bg);
  padding: var(--space-3);
  font-size: var(--font-size-xs);
}
.workflow-node--score-high .workflow-node__score { color: var(--wf-score-high-text); }
.workflow-node--score-mid  .workflow-node__score { color: var(--wf-score-mid-text); }
.workflow-node--score-low  .workflow-node__score { color: var(--wf-score-low-text); }
.workflow-node__label {
  font-weight: var(--bold);
  margin-bottom: var(--space-1);
}
.workflow-node__meta,
.workflow-node__duration,
.workflow-cluster-node__meta {
  color: var(--status-no-data);
}
.workflow-node__meta { margin-top: var(--space-1); }
.workflow-node__error {
  color: var(--status-critical);
  font-weight: var(--bold);
}
.workflow-node[role='button'],
.workflow-cluster-node[role='button'] {
  cursor: pointer;
}
.workflow-node:focus-visible,
.workflow-cluster-node:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}
.workflow-node--dimmed {
  opacity: 0.25;
  pointer-events: none;
}
.workflow-node--critical {
  box-shadow: 0 0 0 3px var(--accent);
  z-index: 1;
}
.workflow-cluster-node {
  width: 240px;
  height: 90px;
  border: 2px dashed var(--wf-cluster-accent);
  border-radius: var(--radius-lg);
  background: var(--wf-cluster-bg);
  padding: var(--space-3);
  font-size: var(--font-size-xs);
  display: flex;
  flex-direction: column;
  justify-content: center;
}
.workflow-node--score-high, .workflow-cluster-node--score-high { border-color: var(--wf-score-high-border); background: var(--wf-score-high-bg); }
.workflow-node--score-mid,  .workflow-cluster-node--score-mid  { border-color: var(--wf-score-mid-border); background: var(--wf-score-mid-bg); }
.workflow-node--score-low,  .workflow-cluster-node--score-low  { border-color: var(--wf-score-low-border); background: var(--wf-score-low-bg); }
.workflow-cluster-node--error { border-color: var(--status-critical); }
.workflow-cluster-node__label {
  font-weight: var(--bold);
  margin-bottom: var(--space-1);
  color: var(--wf-cluster-accent-strong);
}
.workflow-cluster-controls,
.workflow-filter,
.workflow-filter__controls,
.workflow-tabs {
  border-bottom: var(--border-width-thin) solid var(--border-subtle);
  margin-bottom: var(--space-3);
}
.workflow-cluster-controls,
.workflow-filter,
.workflow-filter__controls {
  display: flex;
  flex-wrap: wrap;
  padding: var(--space-2) 0;
}
.workflow-cluster-controls { gap: var(--space-2); }
.workflow-cluster-toggle {
  font-size: var(--font-size-2xs);
  padding: var(--space-1) var(--space-2);
  border-radius: var(--radius);
  border: var(--border-width-thin) solid var(--wf-cluster-accent);
  color: var(--wf-cluster-accent-strong);
  background: transparent;
  cursor: pointer;
  transition: background-color var(--transition-fast), color var(--transition-fast);
}
.workflow-cluster-toggle--collapsed {
  background: var(--wf-cluster-accent);
  color: var(--text-on-accent);
}
.workflow-fallback {
  padding: var(--space-6);
  text-align: center;
}
.workflow-fallback__title {
  font-size: var(--font-size-lg);
  font-weight: var(--bold);
}
.workflow-fallback__subtitle {
  font-size: var(--font-size-xs);
  color: var(--status-no-data);
  margin-top: var(--space-2);
}
.workflow-fallback__empty {
  color: var(--wf-fallback-empty);
}
.workflow-oversize {
  padding: var(--space-6);
}
.workflow-oversize__heading {
  font-weight: var(--bold);
  margin-bottom: var(--space-2);
}
.workflow-oversize__note {
  margin-bottom: var(--space-3);
}
.workflow-oversize__list {
  list-style: disc;
  padding-left: var(--space-5);
}
.workflow-filter {
  align-items: center;
  gap: var(--space-2);
}
.workflow-filter__chip {
  font-size: var(--font-size-2xs);
  cursor: pointer;
}
.workflow-filter__reset {
  cursor: pointer;
  text-decoration: underline;
  margin-left: var(--space-1);
}
.workflow-filter__controls {
  align-items: center;
  gap: var(--space-3);
}
.workflow-filter__label {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-size: var(--font-size-xs);
  color: var(--text-secondary);
}
.workflow-filter__slider {
  width: 100px;
  cursor: pointer;
  accent-color: var(--accent);
}
.workflow-filter__slider-value {
  min-width: 48px;
  color: var(--text-muted);
}
.workflow-filter__export {
  cursor: pointer;
  text-decoration: underline;
  color: var(--text-muted);
  margin-left: auto;
}
.workflow-tab {
  padding: var(--space-2) var(--space-4);
  font-size: var(--font-size-xs);
  font-weight: var(--bold);
  cursor: pointer;
  border-bottom: var(--border-width-thick) solid transparent;
  color: var(--text-muted);
  transition: color var(--transition-fast), border-color var(--transition-fast);
}
.workflow-tab[aria-selected='true'] {
  border-bottom-color: var(--accent);
  color: var(--accent);
}
.shortcut-row {
  padding: var(--space-1) 0;
}
.kbd-chip {
  padding: var(--space-0-5) var(--space-1-5);
  border-radius: var(--radius-sm);
}
.coverage-grid { display: grid; grid-template-columns: var(--coverage-grid-cols); }
.coverage-header-cell {
  writing-mode: vertical-lr;
  text-align: end;
  overflow: hidden;
  max-height: 60px;
}
.coverage-cell {
  width: 28px;
  height: 28px;
  background: var(--coverage-status-color);
  border-radius: var(--radius-bar);
  cursor: default;
  color: var(--text-on-accent);
  opacity: 0.8;
  transition: opacity var(--transition-fast);
}
.coverage-cell[data-hovered] {
  opacity: 1;
}
.coverage-legend-swatch {
  width: 12px;
  height: 12px;
  background: var(--coverage-status-color);
  border-radius: var(--radius-xs);
}
.coverage-gap-list {
  padding-left: var(--space-5);
}
.agent-activity-grid {
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
}
.eval-filter-chip {
  padding: var(--space-1) var(--space-3);
  border-radius: var(--radius);
  border: var(--border-width-thin) solid var(--chip-color);
  background-color: transparent;
  color: var(--chip-color);
