const app = new Hono<{ Bindings: Bindings; Variables: Variables }>();
app.use('/*', cors({
  origin: [
    'https://integritystudio.dev',
    'https://www.aledlie.com',
    'https://aledlie.com',
    'http://localhost:5173',
