  const rawJson: unknown = await res.json().catch(() => null);
  const rows = safeArray(rawJson);
  const roles = rows.flatMap((row) => {
    const parsed = AdminRoleSchema.safeParse(row);
    return parsed.success ? [parsed.data] : [];
  });
  return c.json(roles);
});
