interface DailyBucket {
  timestamp: number;
  scores: number[];
}
function buildDailyBuckets(
  evaluations: Array<{ timestamp: bigint; scoreValue: number }>,
  startMs: number,
  bucketCount: number,
): DailyBucket[] {
  const buckets: DailyBucket[] = Array.from({ length: bucketCount }, (_, i) => ({
    timestamp: startMs + i * TIME_MS.DAY,
    scores: [],
  }));
  for (const ev of evaluations) {
    const ts = Number(ev.timestamp / NANOSECONDS_PER_MILLISECOND_BIGINT);
    const idx = Math.floor((ts - startMs) / TIME_MS.DAY);
