    return {
      timestamp: bucket.timestamp,
      currentStdDev: computeStdDev(bucket.scores) ?? 0,
      baselineStdDev: computeStdDev(baselineScores) ?? 0,
      coverageGapCount,
      totalCoverageCells: i + 1,
      latencyP95Seconds: 0,
      latencyP50Seconds: 0,
      historicalValues: [...cumulativeScores],
