    `var=${cfg.varianceThreshold}`,
    `drop=${cfg.coverageDropoutThreshold}`,
    `λ=${cfg.ewmaLambda ?? '-'}`,
    `win=${cfg.confirmationWindow}`,
    `stab=${cfg.stabilityThreshold ?? '-'}`,
