    const batch = keys.slice(i, i + KV_BATCH_SIZE);
    const tmpFile = join(tmpdir(), `kv-delete-${Date.now()}-${randomBytes(4).toString('hex')}-${i}.json`);
    try {
      writeFileSync(tmpFile, JSON.stringify(batch));
